/* Auto-generated from the approved handbook document. */
window.HANDBOOK_HTML = "<h1><span dir=\"rtl\">الدليل التدريبي لأعضاء هيئة التدريس في بناء الاختبارات الجامعية وتحليلها</span></h1>\n\n<h2><span dir=\"rtl\">مقدمة الدليل</span></h2>\n<p><span dir=\"rtl\">هذا الدليل مرجع تطبيقي لأعضاء هيئة التدريس في جامعة فلسطين التقنية – خضوري، يرافق <strong>سياسة تطوير أساليب التقييم والامتحانات</strong> ويحوّل بنودها إلى ممارسة يومية.</span></p>\n<h3><span dir=\"rtl\">كيف تستخدم الدليل</span></h3>\n<ul>\n<li><p><span dir=\"rtl\">كل وحدة تبدأ بالقواعد الأساسية، ثم <strong>أمثلة متعددة</strong> لكل نوع.</span></p></li>\n<li><p><span dir=\"rtl\">الأمثلة موزعة بين <strong>التخصصات العلمية</strong> (الهندسة، تكنولوجيا المعلومات، الزراعة، العلوم والرياضيات، العلوم الرياضية) و<strong>التخصصات الإنسانية</strong> (اللغة العربية، اللغة الإنجليزية، العلوم التربوية، العلوم الإدارية والمالية، القانون والعلوم الاجتماعية).</span></p></li>\n<li><p><span dir=\"rtl\">في كل نوع تُعرض الأمثلة العلمية والإنسانية متقابلة، لتظهر أن القاعدة نفسها تنطبق على التخصصين.</span></p></li>\n<li><p><span dir=\"rtl\">تُعرض أمثلة <strong>ضعيفة مع نسختها المحسّنة</strong>، لأن رؤية الخطأ وتصحيحه أسرع طريق لتعلم الصياغة.</span></p></li>\n<li><p><span dir=\"rtl\">الإجابة الصحيحة مشار إليها بالعلامة ✓ بعد كل سؤال.</span></p></li>\n<li><p><span dir=\"rtl\">المحكّات الكمية الواردة هنا مطابقة لما في السياسة.</span></p></li>\n</ul>\n<h3><span dir=\"rtl\">النواتج المتوقعة من التدريب</span></h3>\n<p><span dir=\"rtl\">بعد إنهاء البرنامج، يستطيع المتدرب:</span></p>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">صياغة مخرجات تعلم قابلة للقياس وتصنيفها وفق بلوم المعدّل.</span></p></li>\n<li><p><span dir=\"rtl\">بناء مخطط اختبار متوازن لمساق يدرّسه.</span></p></li>\n<li><p><span dir=\"rtl\">كتابة أسئلة موضوعية تقيس التطبيق والتحليل، لا التذكر فقط.</span></p></li>\n<li><p><span dir=\"rtl\">كتابة أسئلة إنشائية محددة المهمة مع سلّم تقدير تحليلي.</span></p></li>\n<li><p><span dir=\"rtl\">حساب معاملات الصعوبة والتمييز وتفسيرها واتخاذ قرار بشأن السؤال.</span></p></li>\n<li><p><span dir=\"rtl\">تصميم مهام تقييم تحدد استخدام الذكاء الاصطناعي وتراعي العدالة.</span></p></li>\n</ol>\n<h3><span dir=\"rtl\">خطة البرنامج التدريبي (12 ساعة)</span></h3>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">الجلسة</span></th>\n<th><span dir=\"rtl\">الموضوع</span></th>\n<th><span dir=\"rtl\">المدة</span></th>\n<th><span dir=\"rtl\">النشاط التطبيقي</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1</td>\n<td><span dir=\"rtl\">مخرجات التعلم وتصنيف بلوم ومخطط الاختبار</span></td>\n<td><span dir=\"rtl\">ساعتان</span></td>\n<td><span dir=\"rtl\">بناء مخطط لمساق المتدرب</span></td>\n</tr>\n<tr>\n<td>2</td>\n<td><span dir=\"rtl\">أسئلة الاختيار من متعدد</span></td>\n<td><span dir=\"rtl\">ساعتان</span></td>\n<td><span dir=\"rtl\">تحسين أسئلة ضعيفة وكتابة أسئلة جديدة</span></td>\n</tr>\n<tr>\n<td>3</td>\n<td><span dir=\"rtl\">الصواب والخطأ والمطابقة والإكمال والأسئلة المعتمدة على سياق</span></td>\n<td><span dir=\"rtl\">ساعتان</span></td>\n<td><span dir=\"rtl\">بناء سياق وأسئلته</span></td>\n</tr>\n<tr>\n<td>4</td>\n<td><span dir=\"rtl\">الأسئلة الإنشائية وسلالم التقدير</span></td>\n<td><span dir=\"rtl\">ساعتان</span></td>\n<td><span dir=\"rtl\">تصحيح إجابات حقيقية ومقارنة العلامات بين المتدربين</span></td>\n</tr>\n<tr>\n<td>5</td>\n<td><span dir=\"rtl\">التحليل الإحصائي للأسئلة</span></td>\n<td><span dir=\"rtl\">ساعتان</span></td>\n<td><span dir=\"rtl\">تحليل نتائج امتحان فعلي</span></td>\n</tr>\n<tr>\n<td>6</td>\n<td><span dir=\"rtl\">الذكاء الاصطناعي والنزاهة والعدالة</span></td>\n<td><span dir=\"rtl\">ساعتان</span></td>\n<td><span dir=\"rtl\">إعادة تصميم مهمة منزلية</span></td>\n</tr>\n</tbody>\n</table></div>\n<p><span dir=\"rtl\">يُطلب من كل متدرب إحضار خطة مساق يدرّسه ونسخة من امتحان سابق له، ليعمل عليهما في الأنشطة.</span></p>\n<h2><span dir=\"rtl\">الوحدة الأولى: مخرجات التعلم وتصنيف بلوم ومخطط الاختبار</span></h2>\n<p><span dir=\"rtl\">السؤال الجيد يبدأ من مخرج تعلم جيد. إذا كان المخرج غامضاً فلن يعرف المدرس ماذا يقيس، ومخطط الاختبار هو الجسر بين المخرجات والأسئلة.</span></p>\n<h3><span dir=\"rtl\">1.1 صياغة مخرجات التعلم</span></h3>\n<p><span dir=\"rtl\">المخرج الجيد = <strong>فعل إجرائي قابل للملاحظة + محتوى محدد + شرط أو معيار عند الحاجة</strong>. تجنب الأفعال غير القابلة للقياس مثل: يعرف، يفهم، يدرك، يقدّر، يلمّ.</span></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">التخصص</span></th>\n<th><span dir=\"rtl\">مخرج ضعيف</span></th>\n<th><span dir=\"rtl\">مخرج محسّن</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">هندسة مدنية</span></td>\n<td><span dir=\"rtl\">أن يفهم الطالب العزوم</span></td>\n<td><span dir=\"rtl\">أن يحسب الطالب العزم الأقصى في كمرة بسيطة محملة بحمل منتظم</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">تكنولوجيا المعلومات</span></td>\n<td><span dir=\"rtl\">أن يعرف الحلقات التكرارية</span></td>\n<td><span dir=\"rtl\">أن يكتب برنامجاً يستخدم حلقة for لمعالجة عناصر قائمة وفق شرط معطى</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الزراعة</span></td>\n<td><span dir=\"rtl\">أن يلمّ بالري بالتنقيط</span></td>\n<td><span dir=\"rtl\">أن يصمم جدول ري بالتنقيط لمحصول محدد بناءً على الاحتياج المائي ونوع التربة</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">اللغة العربية</span></td>\n<td><span dir=\"rtl\">أن يعرف الطالب التشبيه</span></td>\n<td><span dir=\"rtl\">أن يحدد الطالب أركان التشبيه في نص شعري غير مدروس ويبيّن نوعه وأثره الفني</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">العلوم الإدارية</span></td>\n<td><span dir=\"rtl\">أن يدرك أهمية التخطيط</span></td>\n<td><span dir=\"rtl\">أن يعدّ تحليل SWOT لمنشأة صغيرة من واقع دراسة حالة</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">العلوم التربوية</span></td>\n<td><span dir=\"rtl\">أن يفهم نظريات التعلم</span></td>\n<td><span dir=\"rtl\">أن يقارن بين النظرية السلوكية والمعرفية في تفسير موقف صفي معطى</span></td>\n</tr>\n</tbody>\n</table></div>\n<h3><span dir=\"rtl\">1.2 مستويات بلوم المعدّل مع أمثلة متقابلة</span></h3>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">المستوى</span></th>\n<th><span dir=\"rtl\">أفعال مناسبة</span></th>\n<th><span dir=\"rtl\">مثال علمي</span></th>\n<th><span dir=\"rtl\">مثال إنساني</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">التذكر</span></td>\n<td><span dir=\"rtl\">يعدّد، يسمّي، يعرّف، يذكر</span></td>\n<td><span dir=\"rtl\">يذكر وحدة قياس المقاومة الكهربائية</span></td>\n<td><span dir=\"rtl\">يذكر أركان الجملة الاسمية</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الفهم</span></td>\n<td><span dir=\"rtl\">يفسّر، يلخّص، يصنّف، يقارن، يعطي مثالاً</span></td>\n<td><span dir=\"rtl\">يفسّر سبب ارتفاع ملوحة التربة في المناطق الجافة</span></td>\n<td><span dir=\"rtl\">يلخّص الفكرة الرئيسية لمقال نقدي</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">التطبيق</span></td>\n<td><span dir=\"rtl\">يحسب، يطبّق، يستخدم، يحلّ</span></td>\n<td><span dir=\"rtl\">يحسب التيار في دارة معطاة بقانون أوم</span></td>\n<td><span dir=\"rtl\">يُعرب جملة غير مدروسة</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">التحليل</span></td>\n<td><span dir=\"rtl\">يحلّل، يميّز، يستنتج، يكتشف الخطأ</span></td>\n<td><span dir=\"rtl\">يحدد الخطأ المنطقي في مقطع برمجي</span></td>\n<td><span dir=\"rtl\">يحلّل أثر ارتفاع سعر الفائدة على الطلب الاستهلاكي من بيانات معطاة</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">التقييم</span></td>\n<td><span dir=\"rtl\">ينقد، يحكم، يبرّر، يفاضل</span></td>\n<td><span dir=\"rtl\">يفاضل بين تصميمين للمفاعل الحيوي بمعايير الكلفة والكفاءة</span></td>\n<td><span dir=\"rtl\">يحكم على مدى ملاءمة استراتيجية تدريس لصف موصوف</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الإبداع</span></td>\n<td><span dir=\"rtl\">يصمّم، يقترح، يبني، يؤلّف</span></td>\n<td><span dir=\"rtl\">يصمم خوارزمية لتنظيم مواعيد مختبرات الكلية</span></td>\n<td><span dir=\"rtl\">يقترح خطة تسويقية لمنتج زراعي محلي</span></td>\n</tr>\n</tbody>\n</table></div>\n<p><span dir=\"rtl\"><strong>تنبيه مهم:</strong> مستوى السؤال يتحدد بما فعله الطالب في المحاضرة. إذا حلّ المدرس المسألة نفسها أمام الطلبة، ثم وضعها في الامتحان، فهي سؤال <strong>تذكر</strong> وليست تطبيقاً. لذلك تُستخدم في أسئلة المستويات العليا مواقف أو نصوص أو بيانات <strong>جديدة</strong> لم تُعرض بهذا الشكل.</span></p>\n<h3><span dir=\"rtl\">1.3 مثال محلول (تخصص علمي): مخطط الامتحان النهائي لمساق «مبادئ البرمجة»</span></h3>\n<p><span dir=\"rtl\">مساق سنة أولى، 30 ساعة تدريس نظري، الامتحان النهائي 50 علامة في 120 دقيقة: 30 سؤال اختيار من متعدد (30 علامة = 60%) وثلاثة أسئلة إنشائية (20 علامة = 40%).</span></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">الموضوع</span></th>\n<th><span dir=\"rtl\">ساعات</span></th>\n<th><span dir=\"rtl\">الوزن</span></th>\n<th><span dir=\"rtl\">تذكر</span></th>\n<th><span dir=\"rtl\">فهم</span></th>\n<th><span dir=\"rtl\">تطبيق</span></th>\n<th><span dir=\"rtl\">تحليل / تقييم / إبداع</span></th>\n<th><span dir=\"rtl\">العلامة</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">المتغيرات وأنواع البيانات</span></td>\n<td>6</td>\n<td>20%</td>\n<td><span dir=\"rtl\">4 اختيار (4)</span></td>\n<td><span dir=\"rtl\">3 اختيار (3)</span></td>\n<td><span dir=\"rtl\">إجابة قصيرة (2)</span></td>\n<td><span dir=\"rtl\">1 اختيار (1)</span></td>\n<td>10</td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الجمل الشرطية</span></td>\n<td>6</td>\n<td>20%</td>\n<td><span dir=\"rtl\">4 اختيار (4)</span></td>\n<td><span dir=\"rtl\">2 اختيار + إجابة قصيرة (4)</span></td>\n<td><span dir=\"rtl\">2 اختيار (2)</span></td>\n<td>—</td>\n<td>10</td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الحلقات التكرارية</span></td>\n<td>9</td>\n<td>30%</td>\n<td><span dir=\"rtl\">5 اختيار (5)</span></td>\n<td><span dir=\"rtl\">3 اختيار (3)</span></td>\n<td><span dir=\"rtl\">2 اختيار + إجابة قصيرة (4)</span></td>\n<td><span dir=\"rtl\">جزء من السؤال 3 (3)</span></td>\n<td>15</td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الدوال</span></td>\n<td>9</td>\n<td>30%</td>\n<td><span dir=\"rtl\">4 اختيار (4)</span></td>\n<td><span dir=\"rtl\">السؤال 2-أ (4)</span></td>\n<td><span dir=\"rtl\">السؤال 2-ب (4)</span></td>\n<td><span dir=\"rtl\">جزء من السؤال 3 (3)</span></td>\n<td>15</td>\n</tr>\n<tr>\n<td><strong><span dir=\"rtl\">المجموع</span></strong></td>\n<td><strong>30</strong></td>\n<td><strong>100%</strong></td>\n<td><strong>17 (34%)</strong></td>\n<td><strong>14 (28%)</strong></td>\n<td><strong>12 (24%)</strong></td>\n<td><strong>7 (14%)</strong></td>\n<td><strong>50</strong></td>\n</tr>\n</tbody>\n</table></div>\n<p><span dir=\"rtl\">التحقق من المخطط: الأوزان تتبع ساعات التدريس، والتذكر 34% أقل من سقف 40% لمساقات السنة الأولى، والمستويات العليا 14% ضمن المدى 10% – 15%، والتوزيع 60/40 ضمن المدى المعتمد. وزمن الامتحان كافٍ: 30 سؤالاً × 1.5 دقيقة = 45 دقيقة، ونحو 60 دقيقة للأسئلة الإنشائية، والباقي للمراجعة.</span></p>\n<h3><span dir=\"rtl\">1.4 مثال محلول (تخصص إنساني): مخطط الامتحان النصفي لمساق «علم النفس التربوي»</span></h3>\n<p><span dir=\"rtl\">مساق سنة ثانية، الامتحان النصفي 30 علامة في 75 دقيقة: 18 سؤال اختيار من متعدد (18 علامة = 60%) وسؤالان إنشائيان (12 علامة = 40%)، أحدهما مبني على موقف صفي.</span></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">الموضوع</span></th>\n<th><span dir=\"rtl\">الوزن</span></th>\n<th><span dir=\"rtl\">تذكر</span></th>\n<th><span dir=\"rtl\">فهم</span></th>\n<th><span dir=\"rtl\">تطبيق</span></th>\n<th><span dir=\"rtl\">تحليل / تقييم / إبداع</span></th>\n<th><span dir=\"rtl\">العلامة</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">النظريات السلوكية</span></td>\n<td>40%</td>\n<td>3</td>\n<td>3</td>\n<td>3</td>\n<td>3</td>\n<td>12</td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">النظريات المعرفية</span></td>\n<td>30%</td>\n<td>3</td>\n<td>2</td>\n<td>2</td>\n<td>2</td>\n<td>9</td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الدافعية</span></td>\n<td>30%</td>\n<td>2</td>\n<td>2</td>\n<td>3</td>\n<td>2</td>\n<td>9</td>\n</tr>\n<tr>\n<td><strong><span dir=\"rtl\">المجموع</span></strong></td>\n<td><strong>100%</strong></td>\n<td><strong>8 (27%)</strong></td>\n<td><strong>7 (23%)</strong></td>\n<td><strong>8 (27%)</strong></td>\n<td><strong>7 (23%)</strong></td>\n<td><strong>30</strong></td>\n</tr>\n</tbody>\n</table></div>\n<p><span dir=\"rtl\">التحقق من المخطط: التذكر 27% أقل من سقف 30% لمساقات السنة الثانية، والمستويات العليا 23% ضمن المدى 20% – 25%. وتوضع علامات التحليل والتقييم في السؤال الإنشائي المبني على الموقف الصفي وفي أسئلة اختيار معتمدة على سياق.</span></p>\n<h2><span dir=\"rtl\">الوحدة الثانية: أسئلة الاختيار من متعدد</span></h2>\n<p><span dir=\"rtl\">سؤال الاختيار من متعدد الجيد يستطيع قياس التطبيق والتحليل والتقييم، بشرط أن يقدّم موقفاً جديداً وأن تكون مموهاته مبنية على أخطاء حقيقية يقع فيها الطلبة.</span></p>\n<h3><span dir=\"rtl\">2.1 مكونات السؤال</span></h3>\n<ul>\n<li><p><span dir=\"rtl\"><strong>الجذع (Stem):</strong> المشكلة أو السؤال.</span></p></li>\n<li><p><span dir=\"rtl\"><strong>المفتاح (Key):</strong> الإجابة الصحيحة أو الأفضل.</span></p></li>\n<li><p><span dir=\"rtl\"><strong>المموهات (Distractors):</strong> بدائل خاطئة معقولة تجذب من لم يتقن المهارة.</span></p></li>\n</ul>\n<h3><span dir=\"rtl\">2.2 قواعد الصياغة</span></h3>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">الجذع سؤال كامل أو عبارة ناقصة واضحة، يستطيع الطالب المتمكن الإجابة عنه قبل قراءة البدائل.</span></p></li>\n<li><p><span dir=\"rtl\">معظم الكلام في الجذع، والبدائل قصيرة.</span></p></li>\n<li><p><span dir=\"rtl\">أربعة بدائل، إجابة واحدة صحيحة أو أفضل بلا جدال.</span></p></li>\n<li><p><span dir=\"rtl\">بدائل متجانسة في المحتوى والطول والبناء النحوي.</span></p></li>\n<li><p><span dir=\"rtl\">المموهات مأخوذة من الأخطاء الشائعة، أو من ناتج خطوة حل خاطئة.</span></p></li>\n<li><p><span dir=\"rtl\">تجنب «جميع ما سبق» و«لا شيء مما سبق».</span></p></li>\n<li><p><span dir=\"rtl\">تجنب النفي، وعند الضرورة يُبرز: <strong>ليس</strong>، <strong>لا</strong>، <strong>عدا</strong>.</span></p></li>\n<li><p><span dir=\"rtl\">تجنب الكلمات المطلقة (دائماً، أبداً، فقط) التي تكشف البديل الخاطئ.</span></p></li>\n<li><p><span dir=\"rtl\">لا تتداخل البدائل الرقمية، وتُرتب تصاعدياً.</span></p></li>\n<li><p><span dir=\"rtl\">توزيع مواقع المفتاح بين أ وب وج ود بنسب متقاربة.</span></p></li>\n</ol>\n<h3><span dir=\"rtl\">2.3 أمثلة حسب المستوى</span></h3>\n<h4><span dir=\"rtl\">أ) مستوى التذكر</span></h4>\n<p><span dir=\"rtl\"><strong>مثال 2-1 (علمي – الهندسة الكهربائية):</strong> ما وحدة قياس المقاومة الكهربائية في النظام الدولي؟</span></p>\n<ul>\n<li><p><span dir=\"rtl\">أ) الفولت</span></p></li>\n<li><p><span dir=\"rtl\">ب) الأمبير</span></p></li>\n<li><p><span dir=\"rtl\">ج) الأوم ✓</span></p></li>\n<li><p><span dir=\"rtl\">د) الواط</span></p></li>\n</ul>\n<p><span dir=\"rtl\"><strong>مثال 2-2 (إنساني – اللغة العربية):</strong> أيّ الأفعال الآتية من أخوات «كان»؟</span></p>\n<ul>\n<li><p><span dir=\"rtl\">أ) ظنّ</span></p></li>\n<li><p><span dir=\"rtl\">ب) أصبح ✓</span></p></li>\n<li><p><span dir=\"rtl\">ج) علِم</span></p></li>\n<li><p><span dir=\"rtl\">د) عسى</span></p></li>\n</ul>\n<p><span dir=\"rtl\">ملاحظة: المموهات كلها أفعال ناسخة من أبواب أخرى (ظنّ وأخواتها، أفعال المقاربة)، فهي معقولة ومتجانسة.</span></p>\n<h4><span dir=\"rtl\">ب) مستوى الفهم</span></h4>\n<p><span dir=\"rtl\"><strong>مثال 2-3 (علمي – الزراعة):</strong> يُفسَّر ارتفاع ملوحة التربة في المناطق الجافة بأنّ:</span></p>\n<ul>\n<li><p><span dir=\"rtl\">أ) تبخر الماء يفوق الهطول فتتراكم الأملاح قرب السطح ✓</span></p></li>\n<li><p><span dir=\"rtl\">ب) غزارة الهطول تنقل الأملاح من الطبقات العميقة إلى السطح</span></p></li>\n<li><p><span dir=\"rtl\">ج) جذور النباتات الصحراوية تفرز الأملاح في التربة باستمرار</span></p></li>\n<li><p><span dir=\"rtl\">د) انخفاض الحرارة ليلاً يرسّب الأملاح الذائبة في مياه الري</span></p></li>\n</ul>\n<p><span dir=\"rtl\"><strong>مثال 2-4 (علمي – تكنولوجيا المعلومات):</strong> ما القيمة التي يطبعها المقطع الآتي بلغة Python؟</span></p>\n<p>x = 7 // 2<br />\nprint(x)</p>\n<ul>\n<li><p><span dir=\"rtl\">أ) 1</span></p></li>\n<li><p><span dir=\"rtl\">ب) 3 ✓</span></p></li>\n<li><p><span dir=\"rtl\">ج) 3.5</span></p></li>\n<li><p><span dir=\"rtl\">د) 4</span></p></li>\n</ul>\n<p><span dir=\"rtl\">ملاحظة: كل مموه يمثل خطأً محدداً: (1) الخلط مع باقي القسمة %، و(3.5) الخلط مع القسمة العادية /، و(4) الظن بأن الناتج يُقرَّب لأعلى.</span></p>\n<p><span dir=\"rtl\"><strong>مثال 2-5 (إنساني – الاقتصاد):</strong> يُقصد بـ «تكلفة الفرصة البديلة»:</span></p>\n<ul>\n<li><p><span dir=\"rtl\">أ) مجموع التكاليف الثابتة والمتغيرة للإنتاج</span></p></li>\n<li><p><span dir=\"rtl\">ب) التكلفة الإضافية لإنتاج وحدة واحدة أخرى</span></p></li>\n<li><p><span dir=\"rtl\">ج) قيمة أفضل بديل يُضحَّى به عند اتخاذ قرار ما ✓</span></p></li>\n<li><p><span dir=\"rtl\">د) المبلغ المدفوع فعلياً لشراء مورد ما</span></p></li>\n</ul>\n<p><span dir=\"rtl\">ملاحظة: المموهات مفاهيم حقيقية مجاورة (التكلفة الكلية، الحدية، الصريحة)، لذلك تميّز بين من يفهم المفهوم ومن يحفظ المصطلحات.</span></p>\n<p><span dir=\"rtl\"><strong>مثال 2-6 (إنساني – العلوم التربوية):</strong> أيّ المواقف الآتية يمثل «التعزيز السلبي» وفق النظرية السلوكية؟</span></p>\n<ul>\n<li><p><span dir=\"rtl\">أ) يُحرم الطالب من الاستراحة لأنه أزعج زملاءه</span></p></li>\n<li><p><span dir=\"rtl\">ب) يُوبَّخ الطالب أمام زملائه لتأخره عن الحصة</span></p></li>\n<li><p><span dir=\"rtl\">ج) يحصل الطالب على نجمة عندما يحل الواجب كاملاً</span></p></li>\n<li><p><span dir=\"rtl\">د) يُعفى الطالب من الواجب المنزلي عندما يشارك بفاعلية في الحصة ✓</span></p></li>\n</ul>\n<p><span dir=\"rtl\">ملاحظة: السؤال يستهدف الفهم الخاطئ الشائع بأن التعزيز السلبي عقاب. (أ) عقاب سلبي، و(ب) عقاب إيجابي، و(ج) تعزيز إيجابي.</span></p>\n<h4><span dir=\"rtl\">ج) مستوى التطبيق</span></h4>\n<p><span dir=\"rtl\"><strong>مثال 2-7 (علمي – الهندسة الكهربائية):</strong> مقاومتان 4 أوم و 6 أوم موصولتان <strong>على التوالي</strong> ببطارية جهدها 12 فولت. ما شدة التيار في الدارة؟</span></p>\n<ul>\n<li><p><span dir=\"rtl\">أ) 1.2 أمبير ✓</span></p></li>\n<li><p><span dir=\"rtl\">ب) 2 أمبير</span></p></li>\n<li><p><span dir=\"rtl\">ج) 3 أمبير</span></p></li>\n<li><p><span dir=\"rtl\">د) 5 أمبير</span></p></li>\n</ul>\n<p><span dir=\"rtl\">ملاحظة: (5) ناتج التوصيل على التوازي، و(3) و(2) ناتج استخدام مقاومة واحدة فقط.</span></p>\n<p><span dir=\"rtl\"><strong>مثال 2-8 (علمي – الزراعة):</strong> يحتاج حقل مساحته 2 دونم إلى 40 كغم نيتروجين لكل دونم. إذا استُخدم سماد اليوريا (46% نيتروجين)، فكم كيلوغراماً تقريباً يلزم من اليوريا للحقل كله؟</span></p>\n<ul>\n<li><p><span dir=\"rtl\">أ) 37</span></p></li>\n<li><p><span dir=\"rtl\">ب) 80</span></p></li>\n<li><p><span dir=\"rtl\">ج) 87</span></p></li>\n<li><p><span dir=\"rtl\">د) 174 ✓</span></p></li>\n</ul>\n<p><span dir=\"rtl\">ملاحظة: الحل 80 ÷ 0.46 ≈ 174. (37) ناتج الضرب بدل القسمة، و(80) النيتروجين الصافي، و(87) حساب دونم واحد.</span></p>\n<p><span dir=\"rtl\"><strong>مثال 2-9 (إنساني – اللغة العربية):</strong> ما إعراب كلمة «مجتهداً» في جملة: «أصبحَ الطالبُ مجتهداً»؟</span></p>\n<ul>\n<li><p><span dir=\"rtl\">أ) حال منصوبة</span></p></li>\n<li><p><span dir=\"rtl\">ب) خبر أصبح منصوب ✓</span></p></li>\n<li><p><span dir=\"rtl\">ج) مفعول به منصوب</span></p></li>\n<li><p><span dir=\"rtl\">د) تمييز منصوب</span></p></li>\n</ul>\n<p><span dir=\"rtl\"><strong>مثال 2-10 (إنساني – المحاسبة):</strong> بلغت إيرادات شركة 50,000 دينار، وتكاليفها المتغيرة 30,000 دينار، والثابتة 12,000 دينار. كم صافي الربح؟</span></p>\n<ul>\n<li><p><span dir=\"rtl\">أ) 20,000 دينار</span></p></li>\n<li><p><span dir=\"rtl\">ب) 38,000 دينار</span></p></li>\n<li><p><span dir=\"rtl\">ج) 8,000 دينار ✓</span></p></li>\n<li><p><span dir=\"rtl\">د) 42,000 دينار</span></p></li>\n</ul>\n<p><span dir=\"rtl\">ملاحظة: (20,000) هامش المساهمة دون طرح الثابتة، و(38,000) طرح الثابتة فقط، و(42,000) مجموع التكاليف.</span></p>\n<p><span dir=\"rtl\"><strong>مثال 2-11 (إنساني – اللغة الإنجليزية):</strong> Choose the correct form: «If I ______ more free time, I would learn to play the piano.»</span></p>\n<ul>\n<li><p><span dir=\"rtl\">أ) have</span></p></li>\n<li><p><span dir=\"rtl\">ب) had ✓</span></p></li>\n<li><p><span dir=\"rtl\">ج) will have</span></p></li>\n<li><p><span dir=\"rtl\">د) would have</span></p></li>\n</ul>\n<h4><span dir=\"rtl\">د) مستوى التحليل</span></h4>\n<p><span dir=\"rtl\"><strong>مثال 2-12 (علمي – تكنولوجيا المعلومات):</strong> أراد طالب حساب مجموع الأعداد من 1 إلى 5 (الناتج المتوقع 15)، فكتب المقطع الآتي وظهر الناتج 10. ما سبب الخطأ؟</span></p>\n<p>total = 0<br />\nfor i in range(1, 5):<br />\ntotal = total + i<br />\nprint(total)</p>\n<ul>\n<li><p><span dir=\"rtl\">أ) يجب أن تكون القيمة الابتدائية للمتغير total هي 1</span></p></li>\n<li><p><span dir=\"rtl\">ب) الحلقة for لا تصلح للجمع ويجب استخدام while</span></p></li>\n<li><p><span dir=\"rtl\">ج) الأمر print يجب أن يكون داخل الحلقة</span></p></li>\n<li><p><span dir=\"rtl\">د) الدالة range(1, 5) لا تشمل العدد 5 ✓</span></p></li>\n</ul>\n<p><span dir=\"rtl\"><strong>مثال 2-13 (علمي – الزراعة):</strong> يبيّن الجدول نتائج تجربة لأثر كمية السماد النيتروجيني في إنتاجية محصول القمح.</span></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">السماد (كغم/دونم)</span></th>\n<th>0</th>\n<th>20</th>\n<th>40</th>\n<th>60</th>\n<th>80</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">الإنتاج (كغم/دونم)</span></td>\n<td>200</td>\n<td>320</td>\n<td>380</td>\n<td>390</td>\n<td>360</td>\n</tr>\n</tbody>\n</table></div>\n<p><span dir=\"rtl\">أيّ الاستنتاجات الآتية تدعمه البيانات؟</span></p>\n<ul>\n<li><p><span dir=\"rtl\">أ) العلاقة بين السماد والإنتاجية طردية في جميع الكميات</span></p></li>\n<li><p><span dir=\"rtl\">ب) الإنتاجية تزداد بمعدل متناقص ثم تنخفض بعد حد معين ✓</span></p></li>\n<li><p><span dir=\"rtl\">ج) أعلى كمية سماد تحقق أعلى إنتاجية</span></p></li>\n<li><p><span dir=\"rtl\">د) الزيادة من 20 إلى 40 كغم أعطت أكبر زيادة في الإنتاج</span></p></li>\n</ul>\n<p><span dir=\"rtl\">ملاحظة: (د) مموه قوي؛ أكبر زيادة كانت من 0 إلى 20 (120 كغم) وليس من 20 إلى 40 (60 كغم).</span></p>\n<p><span dir=\"rtl\"><strong>مثال 2-14 (إنساني – الأدب العربي):</strong> قال المتنبي: «إذا رأيتَ نيوبَ الليثِ بارزةً … فلا تظنَّنَّ أنَّ الليثَ يبتسمُ». ما الفكرة التي يرمي إليها البيت؟</span></p>\n<ul>\n<li><p><span dir=\"rtl\">أ) الشجاع لا يخاف أعداءه مهما بلغت قوتهم</span></p></li>\n<li><p><span dir=\"rtl\">ب) المظهر الهادئ قد يخفي خطراً فلا تنخدع بالظواهر ✓</span></p></li>\n<li><p><span dir=\"rtl\">ج) على الإنسان أن يبادر إلى مهاجمة خصمه قبل أن يهاجمه</span></p></li>\n<li><p><span dir=\"rtl\">د) الملامح الجادة دليل على قوة الشخصية</span></p></li>\n</ul>\n<p><span dir=\"rtl\"><strong>مثال 2-15 (إنساني – التسويق):</strong> انخفض عدد زبائن متجر في طولكرم بنسبة 30% بعد افتتاح متجر منافس يبيع السلع نفسها بأسعار أقل، مع أن المتجر الأول لم يغيّر أسعاره أو جودة خدماته. ما الاستنتاج الأكثر اتساقاً مع هذه المعطيات؟</span></p>\n<ul>\n<li><p><span dir=\"rtl\">أ) جودة خدمات المتجر الأول تراجعت مؤخراً</span></p></li>\n<li><p><span dir=\"rtl\">ب) الطلب العام على هذه السلع انخفض في السوق</span></p></li>\n<li><p><span dir=\"rtl\">ج) المتجر المنافس يقدم جودة أعلى من المتجر الأول</span></p></li>\n<li><p><span dir=\"rtl\">د) شريحة من الزبائن في هذه السوق حساسة للسعر ✓</span></p></li>\n</ul>\n<p><span dir=\"rtl\">ملاحظة: يقيس السؤال القدرة على التمييز بين ما تدعمه المعطيات وما لا تدعمه. (أ) و(ج) تناقضان المعطيات أو لا تستندان إليها، و(ب) لا تفسر انتقال الزبائن إلى المنافس.</span></p>\n<h4><span dir=\"rtl\">هـ) مستوى التقييم (سؤال أفضل إجابة)</span></h4>\n<p><span dir=\"rtl\"><strong>مثال 2-16 (علمي – هندسة الري):</strong> مزارع في الأغوار يزرع الخضار في منطقة شحيحة المياه ومرتفعة التبخر. أيّ القرارات الآتية هو الأنسب مع مبرره؟</span></p>\n<ul>\n<li><p><span dir=\"rtl\">أ) الري بالغمر، لأنه الأقل كلفة في الإنشاء</span></p></li>\n<li><p><span dir=\"rtl\">ب) الري بالرش، لأنه يغطي مساحة أكبر بسرعة</span></p></li>\n<li><p><span dir=\"rtl\">ج) الري بالتنقيط، لأنه يوصل الماء إلى الجذور ويقلل الفاقد ✓</span></p></li>\n<li><p><span dir=\"rtl\">د) الري بالخطوط، لأنه يناسب جميع أنواع الترب</span></p></li>\n</ul>\n<p><span dir=\"rtl\"><strong>مثال 2-17 (إنساني – العلوم التربوية):</strong> معلم في صف من 40 طالباً بمستويات متفاوتة، وهدفه رفع مشاركة الطلبة منخفضي التحصيل. أيّ الاستراتيجيات الآتية هي الأنسب لهذا الهدف؟</span></p>\n<ul>\n<li><p><span dir=\"rtl\">أ) التعلم التعاوني في مجموعات غير متجانسة بأدوار محددة لكل عضو ✓</span></p></li>\n<li><p><span dir=\"rtl\">ب) المحاضرة المنظمة مع أسئلة شفوية في نهاية الحصة</span></p></li>\n<li><p><span dir=\"rtl\">ج) تقسيم الطلبة حسب التحصيل وإسناد المهام الصعبة للمتفوقين</span></p></li>\n<li><p><span dir=\"rtl\">د) زيادة الواجبات المنزلية الفردية للطلبة الضعفاء</span></p></li>\n</ul>\n<h3><span dir=\"rtl\">2.4 أسئلة ضعيفة ونسختها المحسّنة</span></h3>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th>#</th>\n<th><span dir=\"rtl\">التخصص</span></th>\n<th><span dir=\"rtl\">السؤال الضعيف</span></th>\n<th><span dir=\"rtl\">العيب</span></th>\n<th><span dir=\"rtl\">السؤال المحسّن</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1</td>\n<td><span dir=\"rtl\">العلوم</span></td>\n<td><span dir=\"rtl\">«الماء:» أ) سائل ب) يتكون من الهيدروجين والأكسجين ج) يغلي عند 100°س د) جميع ما سبق</span></td>\n<td><span dir=\"rtl\">جذع ناقص لا يطرح مشكلة، وأكثر من إجابة صحيحة، و«جميع ما سبق»</span></td>\n<td><span dir=\"rtl\">ما درجة غليان الماء النقي عند الضغط الجوي المعياري؟ أ) 90°س ب) 100°س ✓ ج) 110°س د) 120°س</span></td>\n</tr>\n<tr>\n<td>2</td>\n<td><span dir=\"rtl\">تكنولوجيا المعلومات</span></td>\n<td><span dir=\"rtl\">يسمى البرنامج الذي يترجم الشيفرة المصدرية كاملة قبل التنفيذ: أ) مفسّر ب) مترجم يحوّل الشيفرة كاملة إلى لغة الآلة قبل تشغيلها ج) محرر د) متصفح</span></td>\n<td><span dir=\"rtl\">المفتاح أطول البدائل ويكرر كلمات الجذع، والمموهات غير متجانسة</span></td>\n<td><span dir=\"rtl\">… أ) مفسّر (Interpreter) ب) مترجم (Compiler) ✓ ج) مجمّع (Assembler) د) رابط (Linker)</span></td>\n</tr>\n<tr>\n<td>3</td>\n<td><span dir=\"rtl\">الزراعة</span></td>\n<td><span dir=\"rtl\">أيّ مما يلي عنصر غذائي كبير للنبات؟ أ) النيتروجين ب) الذهب ج) البلاستيك د) الزجاج</span></td>\n<td><span dir=\"rtl\">مموهات غير معقولة، فالسؤال لا يميّز</span></td>\n<td><span dir=\"rtl\">… أ) النيتروجين ✓ ب) الحديد ج) الزنك د) المنغنيز (المموهات عناصر صغرى)</span></td>\n</tr>\n<tr>\n<td>4</td>\n<td><span dir=\"rtl\">اللغة العربية</span></td>\n<td><span dir=\"rtl\">أي الكلمات الآتية ليست من الأسماء الخمسة؟ أ) أب ب) أخ ج) ذو د) ابن</span></td>\n<td><span dir=\"rtl\">نفي غير مبرز يغفل عنه الطالب</span></td>\n<td><span dir=\"rtl\">أيّ الكلمات الآتية من الأسماء الخمسة؟ أ) ابن ب) أخ ✓ ج) أمّ د) عمّ</span></td>\n</tr>\n<tr>\n<td>5</td>\n<td><span dir=\"rtl\">العلوم الإدارية</span></td>\n<td><span dir=\"rtl\">الإدارة الديمقراطية: أ) تؤدي دائماً إلى النجاح ب) لا تنجح أبداً ج) تقوم على إشراك العاملين في القرار د) تلغي دور المدير</span></td>\n<td><span dir=\"rtl\">كلمات مطلقة تكشف البدائل الخاطئة</span></td>\n<td><span dir=\"rtl\">النمط القيادي الذي يقوم على إشراك العاملين في اتخاذ القرار هو: أ) الأوتوقراطي ب) الديمقراطي ✓ ج) الترسّلي د) البيروقراطي</span></td>\n</tr>\n<tr>\n<td>6</td>\n<td><span dir=\"rtl\">القياس والتقويم</span></td>\n<td><span dir=\"rtl\">يكون معامل الثبات مقبولاً إذا كان: أ) أكبر من 0.50 ب) أكبر من 0.60 ج) أكبر من 0.70 د) أكبر من 0.80</span></td>\n<td><span dir=\"rtl\">بدائل متداخلة: إذا صح (د) صحت البقية</span></td>\n<td><span dir=\"rtl\">ما الحد الأدنى المقبول لمعامل الثبات في الاختبارات الصفية وفق سياسة الجامعة؟ أ) 0.50 ب) 0.60 ج) 0.70 ✓ د) 0.90</span></td>\n</tr>\n</tbody>\n</table></div>\n<h2><span dir=\"rtl\">الوحدة الثالثة: الصواب والخطأ والمطابقة والإكمال</span></h2>\n<p><span dir=\"rtl\">هذه الأنواع سريعة التصحيح وتغطي محتوى واسعاً، لكنها تميل إلى قياس التذكر. لذلك تُستخدم بنسبة محدودة، ولا يزيد الصواب والخطأ على <strong>10%</strong> من علامة الاختبار.</span></p>\n<h3><span dir=\"rtl\">3.1 أسئلة الصواب والخطأ</span></h3>\n<p><strong><span dir=\"rtl\">قواعد الصياغة:</span></strong></p>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">فكرة واحدة في كل عبارة، صحيحة أو خاطئة بشكل قاطع.</span></p></li>\n<li><p><span dir=\"rtl\">تجنب النفي المزدوج، والكلمات المطلقة (دائماً، أبداً) التي تكشف الخطأ، والكلمات المبهمة (غالباً، أحياناً) التي تجعلها صحيحة غالباً.</span></p></li>\n<li><p><span dir=\"rtl\">عبارات بلغة المدرس لا منقولة حرفياً من الكتاب.</span></p></li>\n<li><p><span dir=\"rtl\">عدد متقارب من العبارات الصحيحة والخاطئة، وطول متقارب.</span></p></li>\n<li><p><span dir=\"rtl\">يُفضل استخدام <strong>الصواب والخطأ المعدّل</strong> (تصحيح الخطأ)، لأنه يقلل أثر التخمين ويقيس الفهم.</span></p></li>\n</ol>\n<p><strong><span dir=\"rtl\">أمثلة علمية:</span></strong></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th>#</th>\n<th><span dir=\"rtl\">التخصص</span></th>\n<th><span dir=\"rtl\">العبارة</span></th>\n<th><span dir=\"rtl\">الإجابة</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>3-1</td>\n<td><span dir=\"rtl\">الهندسة الكهربائية</span></td>\n<td><span dir=\"rtl\">تزداد المقاومة المكافئة عند إضافة مقاومة جديدة على التوازي.</span></td>\n<td><span dir=\"rtl\">خطأ</span></td>\n</tr>\n<tr>\n<td>3-2</td>\n<td><span dir=\"rtl\">تكنولوجيا المعلومات</span></td>\n<td><span dir=\"rtl\">في لغة Python يمكن تعديل عناصر القائمة (list) بعد إنشائها، بخلاف الصف (tuple).</span></td>\n<td><span dir=\"rtl\">صح</span></td>\n</tr>\n<tr>\n<td>3-3</td>\n<td><span dir=\"rtl\">الزراعة</span></td>\n<td><span dir=\"rtl\">تثبّت النباتات البقولية النيتروجين الجوي بمساعدة بكتيريا العقد الجذرية.</span></td>\n<td><span dir=\"rtl\">صح</span></td>\n</tr>\n<tr>\n<td>3-4</td>\n<td><span dir=\"rtl\">الهندسة المدنية</span></td>\n<td><span dir=\"rtl\">تتحمل الخرسانة غير المسلحة إجهادات الشد أكثر مما تتحمل إجهادات الضغط.</span></td>\n<td><span dir=\"rtl\">خطأ</span></td>\n</tr>\n<tr>\n<td>3-5</td>\n<td><span dir=\"rtl\">العلوم الرياضية</span></td>\n<td><span dir=\"rtl\">يُعد الحمض اللبني المصدر الرئيسي للطاقة في التمارين الهوائية طويلة المدة.</span></td>\n<td><span dir=\"rtl\">خطأ</span></td>\n</tr>\n</tbody>\n</table></div>\n<p><strong><span dir=\"rtl\">أمثلة إنسانية:</span></strong></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th>#</th>\n<th><span dir=\"rtl\">التخصص</span></th>\n<th><span dir=\"rtl\">العبارة</span></th>\n<th><span dir=\"rtl\">الإجابة</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>3-6</td>\n<td><span dir=\"rtl\">اللغة العربية</span></td>\n<td><span dir=\"rtl\">يُرفع جمع المذكر السالم بالواو، ويُنصب ويُجر بالياء.</span></td>\n<td><span dir=\"rtl\">صح</span></td>\n</tr>\n<tr>\n<td>3-7</td>\n<td><span dir=\"rtl\">العلوم الإدارية</span></td>\n<td><span dir=\"rtl\">تقتصر الرقابة الإدارية على اكتشاف الأخطاء بعد وقوعها.</span></td>\n<td><span dir=\"rtl\">خطأ</span></td>\n</tr>\n<tr>\n<td>3-8</td>\n<td><span dir=\"rtl\">الاقتصاد</span></td>\n<td><span dir=\"rtl\">إذا ارتفع سعر سلعة عادية مع ثبات العوامل الأخرى تنخفض الكمية المطلوبة منها.</span></td>\n<td><span dir=\"rtl\">صح</span></td>\n</tr>\n<tr>\n<td>3-9</td>\n<td><span dir=\"rtl\">العلوم التربوية</span></td>\n<td><span dir=\"rtl\">يرى بياجيه أن الطفل في مرحلة العمليات المحسوسة قادر على التفكير المجرد الكامل.</span></td>\n<td><span dir=\"rtl\">خطأ</span></td>\n</tr>\n<tr>\n<td>3-10</td>\n<td><span dir=\"rtl\">اللغة الإنجليزية</span></td>\n<td>The present perfect tense is formed with have/has + past participle.</td>\n<td><span dir=\"rtl\">صح</span></td>\n</tr>\n</tbody>\n</table></div>\n<p><span dir=\"rtl\"><strong>الصواب والخطأ المعدّل:</strong> ضع إشارة (✓) أمام العبارة الصحيحة. وإذا كانت خاطئة استبدل الكلمة المكتوبة بخط عريض بما يجعلها صحيحة. (علامة للحكم وعلامة للتصحيح)</span></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th>#</th>\n<th><span dir=\"rtl\">التخصص</span></th>\n<th><span dir=\"rtl\">العبارة</span></th>\n<th><span dir=\"rtl\">الإجابة</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>3-11</td>\n<td><span dir=\"rtl\">الفيزياء</span></td>\n<td><span dir=\"rtl\">وحدة قياس القدرة الكهربائية في النظام الدولي هي <strong>الجول</strong>.</span></td>\n<td><span dir=\"rtl\">خطأ — الواط</span></td>\n</tr>\n<tr>\n<td>3-12</td>\n<td><span dir=\"rtl\">الزراعة</span></td>\n<td><span dir=\"rtl\">تناسب التربة <strong>الرملية</strong> المحاصيل التي تحتاج إلى احتفاظ عالٍ بالماء.</span></td>\n<td><span dir=\"rtl\">خطأ — الطينية</span></td>\n</tr>\n<tr>\n<td>3-13</td>\n<td><span dir=\"rtl\">اللغة العربية</span></td>\n<td><span dir=\"rtl\">الفاعل اسم <strong>منصوب</strong> يدل على من قام بالفعل.</span></td>\n<td><span dir=\"rtl\">خطأ — مرفوع</span></td>\n</tr>\n<tr>\n<td>3-14</td>\n<td><span dir=\"rtl\">المحاسبة</span></td>\n<td><span dir=\"rtl\">تُسجَّل الأصول في الجانب <strong>المدين</strong> من الحساب عند زيادتها.</span></td>\n<td><span dir=\"rtl\">صح</span></td>\n</tr>\n</tbody>\n</table></div>\n<p><strong><span dir=\"rtl\">عبارات ضعيفة ونسختها المحسّنة:</span></strong></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">التخصص</span></th>\n<th><span dir=\"rtl\">العبارة الضعيفة</span></th>\n<th><span dir=\"rtl\">العيب</span></th>\n<th><span dir=\"rtl\">النسخة المحسّنة</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">تكنولوجيا المعلومات</span></td>\n<td><span dir=\"rtl\">لا يُعد عدم حفظ البيانات في ذاكرة RAM بعد انقطاع الكهرباء غير صحيح.</span></td>\n<td><span dir=\"rtl\">نفي مزدوج يربك القارئ</span></td>\n<td><span dir=\"rtl\">تُفقد البيانات المخزنة في ذاكرة RAM عند انقطاع الكهرباء.</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الزراعة</span></td>\n<td><span dir=\"rtl\">الزيتون شجرة معمرة تتحمل الجفاف وتحتاج إلى الري اليومي.</span></td>\n<td><span dir=\"rtl\">فكرتان إحداهما صحيحة والأخرى خاطئة</span></td>\n<td><span dir=\"rtl\">شجرة الزيتون من الأشجار المتحملة للجفاف.</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">اللغة العربية</span></td>\n<td><span dir=\"rtl\">الشعر الجاهلي أفضل أنواع الشعر العربي.</span></td>\n<td><span dir=\"rtl\">رأي لا يمكن الحكم عليه بالصواب أو الخطأ</span></td>\n<td><span dir=\"rtl\">اشتهر الشعر الجاهلي بالمعلقات.</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">العلوم التربوية</span></td>\n<td><span dir=\"rtl\">العقاب لا ينجح أبداً في تعديل السلوك.</span></td>\n<td><span dir=\"rtl\">كلمة مطلقة تكشف الإجابة</span></td>\n<td><span dir=\"rtl\">يرى سكنر أن العقاب يكبت السلوك مؤقتاً دون أن يعلّم سلوكاً بديلاً.</span></td>\n</tr>\n</tbody>\n</table></div>\n<h3><span dir=\"rtl\">3.2 أسئلة المطابقة</span></h3>\n<p><span dir=\"rtl\"><strong>قواعد الصياغة:</strong> قائمتان متجانستان من نوع واحد، لا تزيد القائمة الأولى على 6 إلى 8 بنود، والثانية أطول ببندين على الأقل لمنع الحل بالاستبعاد، والتعليمات توضح هل يُستخدم البند مرة أو أكثر.</span></p>\n<p><span dir=\"rtl\"><strong>مثال 3-15 (علمي – شبكات الحاسوب):</strong> اكتب رمز الوظيفة من العمود (ب) أمام البروتوكول المناسب في العمود (أ). يُستخدم كل رمز مرة واحدة، وفي العمود (ب) رموز زائدة.</span></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">العمود (أ): البروتوكول</span></th>\n<th><span dir=\"rtl\">الإجابة</span></th>\n<th><span dir=\"rtl\">العمود (ب): الوظيفة</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1. DNS</td>\n<td><span dir=\"rtl\">ب</span></td>\n<td><span dir=\"rtl\">أ) نقل صفحات الويب بين الخادم والمتصفح</span></td>\n</tr>\n<tr>\n<td>2. SMTP</td>\n<td><span dir=\"rtl\">د</span></td>\n<td><span dir=\"rtl\">ب) ترجمة أسماء النطاقات إلى عناوين IP</span></td>\n</tr>\n<tr>\n<td>3. DHCP</td>\n<td><span dir=\"rtl\">هـ</span></td>\n<td><span dir=\"rtl\">ج) التحكم الآمن عن بُعد بجهاز آخر</span></td>\n</tr>\n<tr>\n<td>4. HTTP</td>\n<td><span dir=\"rtl\">أ</span></td>\n<td><span dir=\"rtl\">د) إرسال البريد الإلكتروني</span></td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td><span dir=\"rtl\">هـ) توزيع عناوين IP على الأجهزة تلقائياً</span></td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td><span dir=\"rtl\">و) مراقبة أجهزة الشبكة وإدارتها</span></td>\n</tr>\n</tbody>\n</table></div>\n<p><span dir=\"rtl\"><strong>مثال 3-16 (علمي – وقاية النبات):</strong> طابق بين الآفة في العمود (أ) والمحصول الذي تصيبه أساساً في العمود (ب).</span></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">العمود (أ): الآفة</span></th>\n<th><span dir=\"rtl\">الإجابة</span></th>\n<th><span dir=\"rtl\">العمود (ب): المحصول</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">1. ذبابة ثمار الزيتون</span></td>\n<td><span dir=\"rtl\">ج</span></td>\n<td><span dir=\"rtl\">أ) البندورة</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">2. سوسة النخيل الحمراء</span></td>\n<td><span dir=\"rtl\">د</span></td>\n<td><span dir=\"rtl\">ب) القمح</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">3. حفار أنفاق أوراق البندورة (Tuta absoluta)</span></td>\n<td><span dir=\"rtl\">أ</span></td>\n<td><span dir=\"rtl\">ج) الزيتون</span></td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td><span dir=\"rtl\">د) النخيل</span></td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td><span dir=\"rtl\">هـ) الحمضيات</span></td>\n</tr>\n</tbody>\n</table></div>\n<p><span dir=\"rtl\"><strong>مثال 3-17 (إنساني – الأدب العربي):</strong> طابق بين الشاعر في العمود (أ) والعصر الأدبي الذي ينتمي إليه في العمود (ب).</span></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">العمود (أ): الشاعر</span></th>\n<th><span dir=\"rtl\">الإجابة</span></th>\n<th><span dir=\"rtl\">العمود (ب): العصر</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">1. امرؤ القيس</span></td>\n<td><span dir=\"rtl\">أ</span></td>\n<td><span dir=\"rtl\">أ) الجاهلي</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">2. أبو الطيب المتنبي</span></td>\n<td><span dir=\"rtl\">د</span></td>\n<td><span dir=\"rtl\">ب) صدر الإسلام</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">3. أحمد شوقي</span></td>\n<td><span dir=\"rtl\">و</span></td>\n<td><span dir=\"rtl\">ج) الأموي</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">4. جرير</span></td>\n<td><span dir=\"rtl\">ج</span></td>\n<td><span dir=\"rtl\">د) العباسي</span></td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td><span dir=\"rtl\">هـ) الأندلسي</span></td>\n</tr>\n<tr>\n<td></td>\n<td></td>\n<td><span dir=\"rtl\">و) الحديث</span></td>\n</tr>\n</tbody>\n</table></div>\n<p><span dir=\"rtl\"><strong>مثال 3-18 (إنساني – العلوم الإدارية):</strong> طابق بين الموقف الإداري في العمود (أ) والوظيفة الإدارية التي يمثلها في العمود (ب). يجوز استخدام الرمز أكثر من مرة. (مطابقة بمستوى التطبيق)</span></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">العمود (أ): الموقف</span></th>\n<th><span dir=\"rtl\">الإجابة</span></th>\n<th><span dir=\"rtl\">العمود (ب): الوظيفة</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">1. يضع المدير أهداف المبيعات للعام القادم</span></td>\n<td><span dir=\"rtl\">أ</span></td>\n<td><span dir=\"rtl\">أ) التخطيط</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">2. يقارن المدير المبيعات الفعلية بالمستهدفة كل شهر</span></td>\n<td><span dir=\"rtl\">د</span></td>\n<td><span dir=\"rtl\">ب) التنظيم</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">3. يوزّع المدير المهام على الأقسام ويحدد الصلاحيات</span></td>\n<td><span dir=\"rtl\">ب</span></td>\n<td><span dir=\"rtl\">ج) التوجيه</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">4. يعقد المدير لقاءً تحفيزياً مع فريق المبيعات</span></td>\n<td><span dir=\"rtl\">ج</span></td>\n<td><span dir=\"rtl\">د) الرقابة</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">5. يعدّل المدير الخطة بعد اكتشاف انحراف الأداء</span></td>\n<td><span dir=\"rtl\">د</span></td>\n<td></td>\n</tr>\n</tbody>\n</table></div>\n<p><span dir=\"rtl\">ملاحظة: المثال 3-18 أقوى من المطابقة التقليدية، لأن الطالب يصنّف مواقف جديدة بدلاً من ربط مصطلح بتعريفه المحفوظ.</span></p>\n<h3><span dir=\"rtl\">3.3 أسئلة الإكمال</span></h3>\n<p><span dir=\"rtl\"><strong>قواعد الصياغة:</strong> فراغ واحد في نهاية العبارة أو قربها، لكلمة مفتاحية لا لكلمة ثانوية، له إجابة واحدة محددة، وطول الفراغات موحد حتى لا يكشف طول الإجابة. وفي المسائل العددية تُحدد الوحدة المطلوبة ودرجة الدقة.</span></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th>#</th>\n<th><span dir=\"rtl\">التخصص</span></th>\n<th><span dir=\"rtl\">العبارة</span></th>\n<th><span dir=\"rtl\">الإجابة</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>3-19</td>\n<td><span dir=\"rtl\">الهندسة الكهربائية</span></td>\n<td><span dir=\"rtl\">مقاومة يمر بها تيار 2 أمبير وفرق الجهد بين طرفيها 10 فولت، قيمتها تساوي ........ أوم.</span></td>\n<td>5</td>\n</tr>\n<tr>\n<td>3-20</td>\n<td><span dir=\"rtl\">تكنولوجيا المعلومات</span></td>\n<td><span dir=\"rtl\">تُستخدم الكلمة المحجوزة ........ في لغة Python لتعريف دالة جديدة.</span></td>\n<td>def</td>\n</tr>\n<tr>\n<td>3-21</td>\n<td><span dir=\"rtl\">الزراعة</span></td>\n<td><span dir=\"rtl\">يُسمى العنصر الغذائي الذي يُعد المكون المركزي لجزيء الكلوروفيل ........</span></td>\n<td><span dir=\"rtl\">المغنيسيوم</span></td>\n</tr>\n<tr>\n<td>3-22</td>\n<td><span dir=\"rtl\">اللغة العربية</span></td>\n<td><span dir=\"rtl\">تنصب «إنّ» المبتدأ ويُسمى اسمها، وترفع الخبر ويُسمى ........</span></td>\n<td><span dir=\"rtl\">خبرها</span></td>\n</tr>\n<tr>\n<td>3-23</td>\n<td><span dir=\"rtl\">الاقتصاد</span></td>\n<td><span dir=\"rtl\">يُسمى الارتفاع المستمر في المستوى العام للأسعار ........</span></td>\n<td><span dir=\"rtl\">التضخم</span></td>\n</tr>\n<tr>\n<td>3-24</td>\n<td><span dir=\"rtl\">العلوم التربوية</span></td>\n<td><span dir=\"rtl\">يُسمى التقييم الذي يجري أثناء التعلم بهدف تقديم التغذية الراجعة وتحسين الأداء التقييم ........</span></td>\n<td><span dir=\"rtl\">التكويني</span></td>\n</tr>\n</tbody>\n</table></div>\n<p><strong><span dir=\"rtl\">عبارات إكمال ضعيفة ونسختها المحسّنة:</span></strong></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">التخصص</span></th>\n<th><span dir=\"rtl\">العبارة الضعيفة</span></th>\n<th><span dir=\"rtl\">العيب</span></th>\n<th><span dir=\"rtl\">النسخة المحسّنة</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">الفيزياء</span></td>\n<td><span dir=\"rtl\">........ هو ........ الذي يساوي ........</span></td>\n<td><span dir=\"rtl\">فراغات كثيرة، وفراغ في البداية، وعبارة بلا معنى</span></td>\n<td><span dir=\"rtl\">حاصل ضرب الكتلة في التسارع يساوي ........</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الهندسة</span></td>\n<td><span dir=\"rtl\">يبلغ طول الجسر ........</span></td>\n<td><span dir=\"rtl\">إجابات متعددة محتملة (بالمتر، بالقدم، تقريبي)</span></td>\n<td><span dir=\"rtl\">بالاعتماد على المخطط المرفق، طول الجسر بالمتر يساوي ........</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الأدب العربي</span></td>\n<td><span dir=\"rtl\">المتنبي شاعر ........</span></td>\n<td><span dir=\"rtl\">إجابات كثيرة ممكنة (عباسي، كبير، مادح)</span></td>\n<td><span dir=\"rtl\">ينتمي المتنبي إلى العصر الأدبي ........</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">العلوم الإدارية</span></td>\n<td><span dir=\"rtl\">........ هي أولى الوظائف الإدارية</span></td>\n<td><span dir=\"rtl\">الفراغ في البداية يربك القارئ</span></td>\n<td><span dir=\"rtl\">تبدأ العملية الإدارية عادةً بوظيفة ........</span></td>\n</tr>\n</tbody>\n</table></div>\n<h2><span dir=\"rtl\">الوحدة الرابعة: الأسئلة المعتمدة على سياق ودراسات الحالة</span></h2>\n<p><span dir=\"rtl\">هذا النوع هو أقوى أداة موضوعية لقياس التطبيق والتحليل: يُعرض على الطالب سياق جديد (جدول، نص، رسم، مقطع برمجي، موقف)، تتبعه مجموعة أسئلة لا تُجاب إلا باستخدامه.</span></p>\n<h3><span dir=\"rtl\">4.1 قواعد البناء</span></h3>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">السياق <strong>جديد</strong> لم يُعرض في المحاضرة، وقصير بما يكفي.</span></p></li>\n<li><p><span dir=\"rtl\">السياق <strong>ضروري</strong>: لا يستطيع الطالب الإجابة دون قراءته.</span></p></li>\n<li><p><span dir=\"rtl\">الأسئلة <strong>مستقلة</strong>: الخطأ في سؤال لا يؤدي حتماً إلى الخطأ في السؤال التالي.</span></p></li>\n<li><p><span dir=\"rtl\">من 2 إلى 5 أسئلة لكل سياق، بمستويات متدرجة.</span></p></li>\n<li><p><span dir=\"rtl\">اللغة بمستوى الطلبة، حتى لا يصبح السؤال اختباراً في القراءة.</span></p></li>\n</ol>\n<h3><span dir=\"rtl\">4.2 أمثلة علمية</span></h3>\n<h4><span dir=\"rtl\">مثال 4-1 (الزراعة – تحليل التربة)</span></h4>\n<p><span dir=\"rtl\">أُجري تحليل لعينات تربة من ثلاثة حقول في محطة التجارب الزراعية، وكانت النتائج:</span></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">الحقل</span></th>\n<th><span dir=\"rtl\">الرقم الهيدروجيني (pH)</span></th>\n<th><span dir=\"rtl\">الملوحة EC (ديسيسيمنز/م)</span></th>\n<th><span dir=\"rtl\">المادة العضوية (%)</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">أ</span></td>\n<td>8.2</td>\n<td>1.2</td>\n<td>1.5</td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">ب</span></td>\n<td>7.4</td>\n<td>6.5</td>\n<td>2.1</td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">ج</span></td>\n<td>6.8</td>\n<td>0.9</td>\n<td>3.4</td>\n</tr>\n</tbody>\n</table></div>\n<p><span dir=\"rtl\"><strong>السؤال 1 (فهم):</strong> أيّ الحقول يعاني من مشكلة ملوحة تؤثر في معظم المحاصيل؟ أ) أ   ب) ب ✓   ج) ج   د) لا يوجد</span></p>\n<p><span dir=\"rtl\"><strong>السؤال 2 (تحليل):</strong> في الحقل (أ) يُتوقع ضعف جاهزية عنصر: أ) الكالسيوم   ب) الصوديوم   ج) الحديد ✓   د) المغنيسيوم</span></p>\n<p><span dir=\"rtl\"><strong>السؤال 3 (تقييم):</strong> أيّ الحقول أنسب لزراعة محصول حساس للملوحة ويحتاج إلى تربة غنية بالمادة العضوية؟ أ) أ   ب) ب   ج) ج ✓   د) أ أو ج بالدرجة نفسها</span></p>\n<h4><span dir=\"rtl\">مثال 4-2 (تكنولوجيا المعلومات – تتبع الشيفرة)</span></h4>\n<p><span dir=\"rtl\">تحسب الدالة الآتية السعر بعد الخصم في متجر إلكتروني:</span></p>\n<p>def discount(price, member):<br />\nif member and price &gt; 100:<br />\nreturn price * 0.8<br />\nelif member:<br />\nreturn price * 0.9<br />\nreturn price</p>\n<p><span dir=\"rtl\"><strong>السؤال 1 (تطبيق):</strong> ما قيمة discount(150, True)؟ أ) 30.0   ب) 120.0 ✓   ج) 135.0   د) 150</span></p>\n<p><span dir=\"rtl\"><strong>السؤال 2 (تحليل – حالة حدّية):</strong> ما قيمة discount(100, True)؟ أ) 80.0   ب) 90.0 ✓   ج) 100   د) 120.0</span></p>\n<p><span dir=\"rtl\">ملاحظة: السؤال الثاني يكشف من لا يميّز بين &gt; و &gt;=، لأن 100 ليست أكبر من 100.</span></p>\n<h4><span dir=\"rtl\">مثال 4-3 (الهندسة المدنية – ضبط جودة الخرسانة)</span></h4>\n<p><span dir=\"rtl\">تُقبل خلطة خرسانية مصممة لمقاومة 30 ميغاباسكال إذا كان متوسط مقاومة الضغط لثلاث مكعبات بعمر 28 يوماً لا يقل عن 30 ميغاباسكال، <strong>و</strong>لم تقل أي نتيجة فردية عن 26 ميغاباسكال. نتائج المكعبات: 31، 29، 33 ميغاباسكال.</span></p>\n<p><span dir=\"rtl\"><strong>السؤال 1 (تطبيق):</strong> قرار المهندس: أ) تُقبل، لأن المتوسط 31 ولا تقل أي نتيجة عن 26 ✓   ب) تُرفض، لأن إحدى النتائج أقل من 30   ج) تُقبل، لأن أعلى نتيجة 33   د) يُعاد الفحص لأن النتائج متباينة</span></p>\n<p><span dir=\"rtl\"><strong>السؤال 2 (تحليل):</strong> لو كانت نتيجة المكعب الثاني 25 بدلاً من 29، فإن الخلطة: أ) تُقبل لأن المتوسط قريب من 30   ب) تُرفض لسبب واحد هو المتوسط   ج) تُرفض لسبب واحد هو النتيجة الفردية   د) تُرفض لأن الشرطين كليهما غير متحققين ✓</span></p>\n<p><span dir=\"rtl\">ملاحظة: المتوسط يصبح 29.7 (أقل من 30)، والنتيجة 25 أقل من 26.</span></p>\n<h3><span dir=\"rtl\">4.3 أمثلة إنسانية</span></h3>\n<h4><span dir=\"rtl\">مثال 4-4 (الأدب العربي – تحليل نص)</span></h4>\n<p><span dir=\"rtl\">قال أبو تمام في فتح عمورية:</span></p>\n<p><span dir=\"rtl\">«السيفُ أصدقُ إنباءً من الكُتُبِ … في حدِّهِ الحدُّ بينَ الجِدِّ واللَّعِبِ»</span></p>\n<p><span dir=\"rtl\"><strong>السؤال 1 (فهم):</strong> الفكرة التي يؤكدها الشاعر: أ) القوة الفعلية أصدق من التنبؤات المكتوبة ✓   ب) العلم أهم من القوة   ج) الحرب لعب لا جد فيه   د) الكتب مصدر الأخبار الصادقة</span></p>\n<p><span dir=\"rtl\"><strong>السؤال 2 (تحليل):</strong> بين كلمتي «حدّه» و«الحدّ» محسّن بديعي هو: أ) الطباق   ب) المقابلة   ج) السجع   د) الجناس ✓</span></p>\n<p><span dir=\"rtl\"><strong>السؤال 3 (تحليل):</strong> بين «الجدّ» و«اللعب»: أ) جناس تام   ب) طباق ✓   ج) ترادف   د) تورية</span></p>\n<h4><span dir=\"rtl\">مثال 4-5 (العلوم الإدارية – دراسة حالة)</span></h4>\n<p><span dir=\"rtl\">تعاونية زراعية في شمال الضفة تنتج زيت زيتون بكر ممتاز وتبيعه محلياً. تبلغ تكاليفها الثابتة السنوية 24,000 دينار، وسعر بيع اللتر 30 ديناراً، والتكلفة المتغيرة للتر 18 ديناراً. وتشهد السوق المحلية دخول زيوت مستوردة منخفضة السعر، بينما يزداد الطلب الخارجي على المنتجات العضوية المعتمدة.</span></p>\n<p><span dir=\"rtl\"><strong>السؤال 1 (تطبيق):</strong> كمية التعادل السنوية باللتر: أ) 500   ب) 800   ج) 1,333   د) 2,000 ✓</span></p>\n<p><span dir=\"rtl\"><strong>السؤال 2 (فهم):</strong> في تحليل SWOT، يُصنّف دخول الزيوت المستوردة منخفضة السعر ضمن: أ) نقاط القوة   ب) التهديدات ✓   ج) الفرص   د) نقاط الضعف</span></p>\n<p><span dir=\"rtl\"><strong>السؤال 3 (تقييم):</strong> أيّ الاستراتيجيات الآتية تستثمر نقطة قوة لمواجهة التهديد واغتنام الفرصة معاً؟ أ) خفض السعر إلى مستوى الزيوت المستوردة   ب) الحصول على شهادة عضوية والتصدير كمنتج مميز ✓   ج) خلط الزيت المحلي بالمستورد لتقليل التكلفة   د) إيقاف الإنتاج حتى تستقر السوق</span></p>\n<h4><span dir=\"rtl\">مثال 4-6 (العلوم التربوية – موقف صفي)</span></h4>\n<p><span dir=\"rtl\">في حصة رياضيات للصف السابع، لم تستطع طالبة حل مسألة كلامية بمفردها. فطرحت عليها المعلمة سؤالاً يوجّه انتباهها إلى المعطيات، ثم رسمت معها جدولاً لتنظيمها، ثم انسحبت تدريجياً حتى أكملت الطالبة الحل وحدها، وحلّت بعدها مسألة مشابهة دون مساعدة.</span></p>\n<p><span dir=\"rtl\"><strong>السؤال 1 (فهم):</strong> يُسمى ما قامت به المعلمة: أ) التعزيز المتقطع   ب) التشكيل   ج) السقالات التعليمية ✓   د) التعلم بالاكتشاف الحر</span></p>\n<p><span dir=\"rtl\"><strong>السؤال 2 (تحليل):</strong> حلّ الطالبة للمسألة المشابهة دون مساعدة يدل وفق فيجوتسكي على أن المهارة: أ) انتقلت من منطقة النمو القريبة إلى الأداء المستقل ✓   ب) كانت خارج منطقة النمو القريبة   ج) اكتُسبت بالتقليد دون فهم   د) تعتمد على النضج البيولوجي فقط</span></p>\n<h3><span dir=\"rtl\">4.4 سياق ضعيف وسياق محسّن</span></h3>\n<p><span dir=\"rtl\"><strong>سياق ضعيف (الاقتصاد):</strong> «الاقتصاد علم يدرس سلوك الأفراد في تخصيص الموارد النادرة…» ثم السؤال: «ما تعريف الندرة؟». العيب: السؤال يُجاب من الذاكرة دون الحاجة إلى السياق، فالنص زينة لا وظيفة له.</span></p>\n<p><span dir=\"rtl\"><strong>سياق محسّن:</strong> جدول يبيّن سعر الطماطم والكمية المبيعة في سوق الخضار المركزي خلال أربعة أسابيع، ثم سؤال: «احسب مرونة الطلب السعرية بين الأسبوعين الأول والثاني»، وسؤال: «أي الأسابيع يدل على تغيّر في عوامل غير السعر؟». هنا لا يمكن الإجابة دون البيانات.</span></p>\n<h2><span dir=\"rtl\">الوحدة الخامسة: الأسئلة الإنشائية وسلالم التقدير</span></h2>\n<p><span dir=\"rtl\">قوة السؤال الإنشائي في قياس التركيب والتقييم وبناء الحجة، وضعفه في ذاتية التصحيح. الحل هو سؤال محدد المهمة، وسلّم تقدير مُعدّ قبل التصحيح.</span></p>\n<h3><span dir=\"rtl\">5.1 أنواع الأسئلة الإنشائية</span></h3>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">النوع</span></th>\n<th><span dir=\"rtl\">الطول التقريبي للإجابة</span></th>\n<th><span dir=\"rtl\">العلامة المعتادة</span></th>\n<th><span dir=\"rtl\">أداة التصحيح</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">الإجابة القصيرة</span></td>\n<td><span dir=\"rtl\">سطر إلى ثلاثة أسطر</span></td>\n<td>1 – 3</td>\n<td><span dir=\"rtl\">نموذج إجابة بنقاط</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">المقالي المقيد</span></td>\n<td><span dir=\"rtl\">فقرة إلى صفحة (100 – 250 كلمة)</span></td>\n<td>4 – 8</td>\n<td><span dir=\"rtl\">نموذج إجابة بعناصر وعلامات</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">المقالي الممتد</span></td>\n<td><span dir=\"rtl\">صفحتان فأكثر</span></td>\n<td>10 – 20</td>\n<td><span dir=\"rtl\">سلّم تقدير تحليلي بمستويات</span></td>\n</tr>\n</tbody>\n</table></div>\n<h3><span dir=\"rtl\">5.2 قواعد الصياغة</span></h3>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">فعل إجرائي واضح: قارن، علّل، حلّل، قيّم، صمّم، اقترح. وتجنب: اكتب ما تعرفه، تحدث عن، ناقش (دون محاور).</span></p></li>\n<li><p><span dir=\"rtl\">تحديد النطاق: عدد النقاط أو المحاور أو حدود الكلمات.</span></p></li>\n<li><p><span dir=\"rtl\">كتابة العلامة بجانب السؤال، لأنها توجّه الطالب إلى العمق المطلوب.</span></p></li>\n<li><p><span dir=\"rtl\">لا أسئلة اختيارية («أجب عن سؤالين من ثلاثة»)، لأن الطلبة يصبحون يؤدون اختبارات مختلفة لا تُقارن نتائجها.</span></p></li>\n<li><p><span dir=\"rtl\">إعداد نموذج الإجابة والسلّم <strong>قبل</strong> الامتحان، لأن كتابته تكشف غموض السؤال.</span></p></li>\n</ol>\n<h3><span dir=\"rtl\">5.3 أسئلة الإجابة القصيرة</span></h3>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th>#</th>\n<th><span dir=\"rtl\">التخصص</span></th>\n<th><span dir=\"rtl\">السؤال</span></th>\n<th><span dir=\"rtl\">نموذج الإجابة وتوزيع العلامة</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>5-1</td>\n<td><span dir=\"rtl\">الهندسة الكهربائية</span></td>\n<td><span dir=\"rtl\">اذكر سببين لاستخدام التوصيل على التوازي في التمديدات المنزلية. (2)</span></td>\n<td><span dir=\"rtl\">أي سببين، علامة لكل سبب: كل جهاز يأخذ الجهد الكامل؛ تعطل جهاز لا يوقف الأجهزة الأخرى؛ إمكانية تشغيل كل جهاز بمفتاح مستقل.</span></td>\n</tr>\n<tr>\n<td>5-2</td>\n<td><span dir=\"rtl\">تكنولوجيا المعلومات</span></td>\n<td><span dir=\"rtl\">ما الفرق بين الخطأ النحوي (Syntax Error) والخطأ المنطقي (Logic Error)؟ أعط مثالاً لكل منهما. (3)</span></td>\n<td><span dir=\"rtl\">الفرق (1): النحوي يمنع تشغيل البرنامج، والمنطقي يُشغّله بنتيجة خاطئة. مثال نحوي (1): نسيان النقطتين بعد if. مثال منطقي (1): استخدام &gt; بدل &gt;= في شرط النجاح.</span></td>\n</tr>\n<tr>\n<td>5-3</td>\n<td><span dir=\"rtl\">الزراعة</span></td>\n<td><span dir=\"rtl\">علّل: يُنصح بزراعة البقوليات قبل القمح في الدورة الزراعية. (2)</span></td>\n<td><span dir=\"rtl\">تثبيت النيتروجين الجوي يرفع خصوبة التربة ويقلل الحاجة للسماد (1)؛ كسر دورة الآفات والأمراض الخاصة بالقمح (1).</span></td>\n</tr>\n<tr>\n<td>5-4</td>\n<td><span dir=\"rtl\">اللغة العربية</span></td>\n<td><span dir=\"rtl\">أعرب الكلمتين المكتوبتين بخط عريض: «إنّ <strong>العلمَ</strong> <strong>نورٌ</strong>». (2)</span></td>\n<td><span dir=\"rtl\">العلمَ: اسم إنّ منصوب وعلامة نصبه الفتحة (1). نورٌ: خبر إنّ مرفوع وعلامة رفعه الضمة (1).</span></td>\n</tr>\n<tr>\n<td>5-5</td>\n<td><span dir=\"rtl\">العلوم الإدارية</span></td>\n<td><span dir=\"rtl\">عرّف «تفويض السلطة»، واذكر شرطاً واحداً لنجاحه. (2)</span></td>\n<td><span dir=\"rtl\">التعريف (1): منح المرؤوس صلاحية اتخاذ قرارات في مهام محددة مع بقاء المسؤولية النهائية على المفوّض. الشرط (1): تكافؤ السلطة مع المسؤولية، أو وضوح حدود المهمة، أو كفاءة المفوَّض إليه.</span></td>\n</tr>\n<tr>\n<td>5-6</td>\n<td><span dir=\"rtl\">العلوم التربوية</span></td>\n<td><span dir=\"rtl\">اذكر فرقين بين التقويم التكويني والتقويم الختامي. (2)</span></td>\n<td><span dir=\"rtl\">أي فرقين: التوقيت (أثناء التعلم / في نهايته)؛ الهدف (تحسين / إصدار حكم)؛ الأثر في العلامة (منخفض أو معدوم / مرتفع).</span></td>\n</tr>\n</tbody>\n</table></div>\n<h3><span dir=\"rtl\">5.4 الأسئلة المقالية المقيدة</span></h3>\n<p><span dir=\"rtl\"><strong>مثال 5-7 (علمي – هندسة الري):</strong> قارن بين الري بالتنقيط والري بالرش من حيث: كفاءة استخدام المياه، والكلفة الأولية، وملاءمة المحاصيل. (6 علامات، في حدود 150 كلمة)</span></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">المحور</span></th>\n<th><span dir=\"rtl\">التنقيط</span></th>\n<th><span dir=\"rtl\">الرش</span></th>\n<th><span dir=\"rtl\">العلامة</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">كفاءة المياه</span></td>\n<td><span dir=\"rtl\">مرتفعة، الماء يصل إلى منطقة الجذور</span></td>\n<td><span dir=\"rtl\">أقل، فاقد بالتبخر والرياح</span></td>\n<td>2</td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الكلفة الأولية</span></td>\n<td><span dir=\"rtl\">أعلى عادةً لكثرة الخطوط والنقاطات والفلاتر</span></td>\n<td><span dir=\"rtl\">أقل نسبياً للمساحات الواسعة</span></td>\n<td>2</td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">ملاءمة المحاصيل</span></td>\n<td><span dir=\"rtl\">الخضار والأشجار المزروعة في خطوط</span></td>\n<td><span dir=\"rtl\">المسطحات الخضراء والمحاصيل الحقلية الكثيفة</span></td>\n<td>2</td>\n</tr>\n</tbody>\n</table></div>\n<p><span dir=\"rtl\">لكل محور علامتان: علامة لكل نظام. ولا تُمنح العلامة الكاملة إذا وُصف نظام واحد دون مقارنة.</span></p>\n<p><span dir=\"rtl\"><strong>مثال 5-8 (علمي – تكنولوجيا المعلومات):</strong> اكتب دالة بلغة Python تستقبل قائمة علامات وتعيد عدد الطلبة الناجحين (العلامة 50 فأكثر)، ثم بيّن ناتجها للقائمة [45, 50, 72, 38, 90]. (6 علامات)</span></p>\n<p><span dir=\"rtl\">نموذج الإجابة:</span></p>\n<p>def count_passed(marks):<br />\ncount = 0<br />\nfor m in marks:<br />\nif m &gt;= 50:<br />\ncount += 1<br />\nreturn count<br />\n<br />\nprint(count_passed([45, 50, 72, 38, 90])) # 3</p>\n<p><span dir=\"rtl\">توزيع العلامة: تعريف الدالة بمعامل (1)، المرور على العناصر (1)، الشرط &gt;= 50 بالتحديد (1)، العدّ الصحيح (1)، إعادة القيمة (1)، الناتج 3 (1). تُقبل أي صيغة صحيحة مكافئة، مثل sum مع مولّد.</span></p>\n<p><span dir=\"rtl\"><strong>مثال 5-9 (إنساني – البلاغة العربية):</strong> وضّح الفكرة في قول المتنبي: «إذا رأيتَ نيوبَ الليثِ بارزةً … فلا تظنَّنَّ أنَّ الليثَ يبتسمُ»، ثم حدّد نوع الصورة الفنية فيه وبيّن أثرها في المعنى. (6 علامات)</span></p>\n<p><span dir=\"rtl\">توزيع العلامة: الفكرة (2): لا تغتر بمظهر العدو الهادئ أو المبتسم فقد يخفي الشر. نوع الصورة (2): تشبيه ضمني، إذ يُفهم تشبيه العدو المبتسم بالليث الذي يكشف أنيابه دون تصريح. الأثر (2): تقديم الحكمة مع دليلها المحسوس، فيصبح المعنى أقنع وأرسخ.</span></p>\n<p><span dir=\"rtl\"><strong>مثال 5-10 (إنساني – الاقتصاد):</strong> حلّل أثر ارتفاع أسعار الوقود على أسعار الخضار في السوق المحلية، مستخدماً مفهومي العرض والطلب. (6 علامات)</span></p>\n<p><span dir=\"rtl\">توزيع العلامة: ارتفاع تكاليف النقل والضخ والتدفئة في الإنتاج (2)، انتقال منحنى العرض إلى اليسار مع ثبات الطلب (2)، ارتفاع سعر التوازن وانخفاض الكمية التوازنية (2). ويُقبل الرسم البياني الصحيح بديلاً عن الشرح في العنصرين الثاني والثالث.</span></p>\n<h3><span dir=\"rtl\">5.5 الأسئلة المقالية الممتدة مع سلّم تقدير تحليلي</span></h3>\n<p><span dir=\"rtl\"><strong>مثال 5-11 (علمي – هندسة الحاسوب والزراعة الذكية):</strong> اقترح تصميماً لنظام ري ذكي لبيت بلاستيكي في طولكرم يعتمد على حساسات رطوبة التربة. بيّن مكونات النظام، ومنطق اتخاذ قرار الري، وطريقة تقدير التوفير في المياه، والقيود المحتملة وكيفية التعامل معها. (15 علامة)</span></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">المعيار</span></th>\n<th><span dir=\"rtl\">ممتاز</span></th>\n<th><span dir=\"rtl\">جيد</span></th>\n<th><span dir=\"rtl\">مقبول</span></th>\n<th><span dir=\"rtl\">ضعيف</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">المكونات (4)</span></td>\n<td><span dir=\"rtl\">حساسات، متحكم، صمام كهربائي، مصدر طاقة، اتصال، مع دور كل منها (4)</span></td>\n<td><span dir=\"rtl\">معظم المكونات مع أدوار موجزة (3)</span></td>\n<td><span dir=\"rtl\">مكونات أساسية دون أدوار (2)</span></td>\n<td><span dir=\"rtl\">ذكر عام غير مترابط (0 – 1)</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">منطق القرار (4)</span></td>\n<td><span dir=\"rtl\">عتبات رطوبة محددة للتشغيل والإيقاف مع مراعاة الوقت أو الحرارة، بمخطط انسيابي أو شيفرة وهمية (4)</span></td>\n<td><span dir=\"rtl\">عتبات واضحة دون عوامل إضافية (3)</span></td>\n<td><span dir=\"rtl\">وصف عام للتشغيل عند الجفاف (2)</span></td>\n<td><span dir=\"rtl\">غائب أو متناقض (0 – 1)</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">تقدير التوفير (4)</span></td>\n<td><span dir=\"rtl\">طريقة قياس واضحة (مقارنة الاستهلاك قبل وبعد) مع مثال عددي معقول (4)</span></td>\n<td><span dir=\"rtl\">طريقة مناسبة دون مثال عددي (3)</span></td>\n<td><span dir=\"rtl\">ادعاء بالتوفير دون طريقة (2)</span></td>\n<td><span dir=\"rtl\">غائب (0 – 1)</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">القيود والحلول (3)</span></td>\n<td><span dir=\"rtl\">قيدان واقعيان على الأقل (انقطاع الكهرباء، معايرة الحساسات، الكلفة) مع حل لكل منهما (3)</span></td>\n<td><span dir=\"rtl\">قيدان دون حلول كافية (2)</span></td>\n<td><span dir=\"rtl\">قيد واحد (1)</span></td>\n<td><span dir=\"rtl\">غائب (0)</span></td>\n</tr>\n</tbody>\n</table></div>\n<p><span dir=\"rtl\"><strong>مثال 5-12 (إنساني – العلوم التربوية):</strong> يرى بعض التربويين أن الامتحانات النهائية التحريرية لم تعد الأداة الأنسب لقياس تعلم الطلبة في عصر الذكاء الاصطناعي. ناقش هذا الرأي مؤيداً أو معارضاً، مستنداً إلى مبدأين على الأقل من مبادئ التقويم (الصدق، الثبات، العدالة، النزاهة)، ومردّاً على حجة واحدة للرأي المخالف. (15 علامة)</span></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">المعيار</span></th>\n<th><span dir=\"rtl\">ممتاز</span></th>\n<th><span dir=\"rtl\">جيد</span></th>\n<th><span dir=\"rtl\">مقبول</span></th>\n<th><span dir=\"rtl\">ضعيف</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">وضوح الموقف (3)</span></td>\n<td><span dir=\"rtl\">موقف صريح منذ البداية وثابت حتى النهاية (3)</span></td>\n<td><span dir=\"rtl\">موقف واضح مع بعض التردد (2)</span></td>\n<td><span dir=\"rtl\">موقف يُستنتج ضمناً (1)</span></td>\n<td><span dir=\"rtl\">لا موقف (0)</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الحجج والأدلة (5)</span></td>\n<td><span dir=\"rtl\">مبدآن موظفان بدقة مع أمثلة من الواقع الجامعي (5)</span></td>\n<td><span dir=\"rtl\">مبدآن بشرح مقبول دون أمثلة (3 – 4)</span></td>\n<td><span dir=\"rtl\">مبدأ واحد أو فهم سطحي (2)</span></td>\n<td><span dir=\"rtl\">آراء شخصية بلا مستند (0 – 1)</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الرد على الرأي المخالف (4)</span></td>\n<td><span dir=\"rtl\">يعرض الحجة المقابلة بإنصاف ويرد عليها بمنطق (4)</span></td>\n<td><span dir=\"rtl\">يعرضها ويرد عليها باختصار (3)</span></td>\n<td><span dir=\"rtl\">يعرضها دون رد (1 – 2)</span></td>\n<td><span dir=\"rtl\">غائب (0)</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">التنظيم واللغة (3)</span></td>\n<td><span dir=\"rtl\">مقدمة وعرض وخاتمة بلغة سليمة (3)</span></td>\n<td><span dir=\"rtl\">تنظيم جيد مع أخطاء قليلة (2)</span></td>\n<td><span dir=\"rtl\">أفكار متناثرة (1)</span></td>\n<td><span dir=\"rtl\">غير مفهوم (0)</span></td>\n</tr>\n</tbody>\n</table></div>\n<p><span dir=\"rtl\">ملاحظة: الموقف المؤيد والمعارض يستحقان العلامة الكاملة بالتساوي، لأن المقياس هو جودة الاستدلال لا الموقف نفسه.</span></p>\n<h3><span dir=\"rtl\">5.6 أسئلة إنشائية ضعيفة ونسختها المحسّنة</span></h3>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">التخصص</span></th>\n<th><span dir=\"rtl\">السؤال الضعيف</span></th>\n<th><span dir=\"rtl\">السؤال المحسّن</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">تكنولوجيا المعلومات</span></td>\n<td><span dir=\"rtl\">اكتب ما تعرفه عن الحلقات التكرارية.</span></td>\n<td><span dir=\"rtl\">قارن بين حلقة for وحلقة while من حيث موقف استخدام كل منهما، مع مثال برمجي قصير لكل حالة. (6)</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الزراعة</span></td>\n<td><span dir=\"rtl\">تحدث عن التربة.</span></td>\n<td><span dir=\"rtl\">فسّر ثلاثة أسباب لانخفاض خصوبة التربة في البيوت البلاستيكية مع تكرار الزراعة، واقترح إجراءً علاجياً لكل سبب. (6)</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الهندسة المدنية</span></td>\n<td><span dir=\"rtl\">ناقش الخرسانة المسلحة.</span></td>\n<td><span dir=\"rtl\">علّل وضع حديد التسليح في الجزء السفلي من الكمرة البسيطة، مستعيناً برسم توزيع الإجهادات. (5)</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الأدب العربي</span></td>\n<td><span dir=\"rtl\">ناقش الشعر العباسي.</span></td>\n<td><span dir=\"rtl\">وضّح مظهرين من مظاهر التجديد في مقدمة القصيدة العباسية، مستشهداً ببيت لكل مظهر. (6)</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">العلوم التربوية</span></td>\n<td><span dir=\"rtl\">ما رأيك في التعليم الإلكتروني؟</span></td>\n<td><span dir=\"rtl\">قيّم تجربة التعليم الإلكتروني في الجامعات الفلسطينية خلال الظروف الطارئة من حيث: إتاحة الوصول، وجودة التفاعل، وعدالة التقييم، مقدماً توصيتين قابلتين للتطبيق. (10)</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">العلوم الإدارية</span></td>\n<td><span dir=\"rtl\">اشرح التسويق.</span></td>\n<td><span dir=\"rtl\">اقترح مزيجاً تسويقياً (المنتج، السعر، التوزيع، الترويج) لمنتج أجبان محلية يستهدف طلبة الجامعة، مع تبرير كل عنصر. (8)</span></td>\n</tr>\n</tbody>\n</table></div>\n<h3><span dir=\"rtl\">5.7 سلّم تقدير كلي للأسئلة القصيرة المفتوحة</span></h3>\n<p><span dir=\"rtl\">يصلح لأسئلة مثل: «اشرح في فقرة لماذا …»، في أي تخصص.</span></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">العلامة</span></th>\n<th><span dir=\"rtl\">الوصف</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>3</td>\n<td><span dir=\"rtl\">إجابة دقيقة ومكتملة، مع تبرير أو مثال مناسب، ومصطلحات صحيحة</span></td>\n</tr>\n<tr>\n<td>2</td>\n<td><span dir=\"rtl\">إجابة صحيحة في جوهرها مع نقص في التبرير أو خطأ بسيط</span></td>\n</tr>\n<tr>\n<td>1</td>\n<td><span dir=\"rtl\">فهم جزئي مع خلط في المفاهيم</span></td>\n</tr>\n<tr>\n<td>0</td>\n<td><span dir=\"rtl\">إجابة خاطئة أو غير مرتبطة أو متروكة</span></td>\n</tr>\n</tbody>\n</table></div>\n<h3><span dir=\"rtl\">5.8 خطوات تصحيح الأسئلة الإنشائية</span></h3>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">راجع السلّم على 5 إلى 10 أوراق عشوائية قبل التصحيح الفعلي، وعدّله إذا ظهرت إجابات صحيحة غير متوقعة.</span></p></li>\n<li><p><span dir=\"rtl\">في المساقات متعددة الشُعب، يصحح المصححون الأوراق نفسها منفصلين، ثم يناقشون الفروق لتوحيد الفهم (جلسة معايرة).</span></p></li>\n<li><p><span dir=\"rtl\">صحّح أفقياً: السؤال نفسه لجميع الطلبة، مع خلط ترتيب الأوراق بين الأسئلة.</span></p></li>\n<li><p><span dir=\"rtl\">اكتب العلامة الجزئية بجانب كل عنصر، لا المجموع فقط، لتسهيل المراجعة والتظلم.</span></p></li>\n<li><p><span dir=\"rtl\">لا تخصم على الأخطاء اللغوية في المساقات غير اللغوية إلا إذا كان ذلك معياراً معلناً مسبقاً في السلّم.</span></p></li>\n<li><p><span dir=\"rtl\">الإجابة الطويلة لا تعني بالضرورة إجابة جيدة؛ العلامة تُمنح للعناصر المحددة في السلّم.</span></p></li>\n</ol>\n<h2><span dir=\"rtl\">الوحدة السادسة: التحليل الإحصائي للأسئلة</span></h2>\n<p><span dir=\"rtl\">بعد كل امتحان نهائي يجيب التحليل عن سؤالين: هل كان السؤال مناسب الصعوبة؟ وهل ميّز بين من يتقن المادة ومن لا يتقنها؟ الطريقة واحدة في جميع التخصصات، وتوفرها منصات التعلم الإلكتروني (مثل تقارير إحصاءات الاختبار في Moodle) أو جدول Excel بسيط.</span></p>\n<h3><span dir=\"rtl\">6.1 الخطوات</span></h3>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">رتّب أوراق الطلبة تنازلياً حسب العلامة الكلية.</span></p></li>\n<li><p><span dir=\"rtl\">خذ أعلى 27% (الفئة العليا U) وأدنى 27% (الفئة الدنيا L).</span></p></li>\n<li><p><span dir=\"rtl\">لكل سؤال، عدّ من أجاب إجابة صحيحة في كل فئة، وعدد من اختار كل بديل.</span></p></li>\n<li><p><span dir=\"rtl\">احسب المعاملات وقارنها بالمحكّات، ثم اتخذ القرار.</span></p></li>\n</ol>\n<h3><span dir=\"rtl\">6.2 المعادلات</span></h3>\n<p><span dir=\"rtl\">معامل الصعوبة (نسبة الإجابات الصحيحة في الفئتين):</span></p>\n<p class=\"formula\">p = (U + L) ÷ 2n</p>\n<p><span dir=\"rtl\">معامل التمييز:</span></p>\n<p class=\"formula\">D = (U − L) ÷ n</p>\n<p><span dir=\"rtl\">حيث U وL عدد الإجابات الصحيحة في الفئتين العليا والدنيا، وn عدد الطلبة في كل فئة.</span></p>\n<p><span dir=\"rtl\">معامل ثبات كودر-ريتشاردسون (KR-20) للاختبارات ذات الأسئلة المصححة بـ 0 أو 1:</span></p>\n<p class=\"formula\">KR-20 = [k ÷ (k − 1)] × [1 − (Σ pᵢqᵢ ÷ σ²)]</p>\n<p><span dir=\"rtl\">حيث k عدد الأسئلة، وp نسبة الإجابة الصحيحة للسؤال، وq = 1 − p، وσ² تباين العلامات الكلية.</span></p>\n<h3><span dir=\"rtl\">6.3 مثال محلول (تخصص علمي): امتحان «مبادئ البرمجة»</span></h3>\n<p><span dir=\"rtl\">تقدم للامتحان 40 طالباً، فكل فئة = 27% × 40 ≈ <strong>11 طالباً</strong>.</span></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">السؤال</span></th>\n<th>U (من 11)</th>\n<th>L (من 11)</th>\n<th>p</th>\n<th>D</th>\n<th><span dir=\"rtl\">التشخيص</span></th>\n<th><span dir=\"rtl\">القرار</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1</td>\n<td>9</td>\n<td>4</td>\n<td>0.59</td>\n<td>0.45</td>\n<td><span dir=\"rtl\">صعوبة مثالية وتمييز ممتاز</span></td>\n<td><span dir=\"rtl\">يبقى في البنك</span></td>\n</tr>\n<tr>\n<td>2</td>\n<td>11</td>\n<td>10</td>\n<td>0.95</td>\n<td>0.09</td>\n<td><span dir=\"rtl\">سهل جداً، لا يميّز</span></td>\n<td><span dir=\"rtl\">يُعدَّل أو يُستبدل، إلا إذا كان يقيس مهارة أساسية مقصودة</span></td>\n</tr>\n<tr>\n<td>3</td>\n<td>3</td>\n<td>2</td>\n<td>0.23</td>\n<td>0.09</td>\n<td><span dir=\"rtl\">صعب جداً ولا يميّز</span></td>\n<td><span dir=\"rtl\">يُفحص: غموض في الصياغة؟ محتوى لم يُدرَّس جيداً؟</span></td>\n</tr>\n<tr>\n<td>4</td>\n<td>4</td>\n<td>7</td>\n<td>0.50</td>\n<td>−0.27</td>\n<td><span dir=\"rtl\">تمييز سالب: الضعفاء أجابوا أفضل</span></td>\n<td><span dir=\"rtl\">يُفحص المفتاح فوراً (انظر الجدول التالي)</span></td>\n</tr>\n<tr>\n<td>5</td>\n<td>8</td>\n<td>5</td>\n<td>0.59</td>\n<td>0.27</td>\n<td><span dir=\"rtl\">صعوبة جيدة وتمييز مقبول</span></td>\n<td><span dir=\"rtl\">يُراجع مموهاته لتحسينه</span></td>\n</tr>\n</tbody>\n</table></div>\n<p><span dir=\"rtl\">مثال حساب السؤال 1: p = (9 + 4) ÷ 22 = 0.59، وD = (9 − 4) ÷ 11 = 0.45.</span></p>\n<p><span dir=\"rtl\"><strong>تحليل المموهات للسؤال 4</strong> (المفتاح المسجل = أ):</span></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">البديل</span></th>\n<th><span dir=\"rtl\">الفئة العليا</span></th>\n<th><span dir=\"rtl\">الفئة الدنيا</span></th>\n<th><span dir=\"rtl\">القراءة</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">أ (المفتاح المسجل)</span></td>\n<td>4</td>\n<td>7</td>\n<td><span dir=\"rtl\">يجذب الضعفاء أكثر: مؤشر خطر</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">ب</span></td>\n<td>6</td>\n<td>1</td>\n<td><span dir=\"rtl\">يجذب المتفوقين: الأرجح أنه المفتاح الصحيح، أو أن السؤال له إجابتان</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">ج</span></td>\n<td>1</td>\n<td>2</td>\n<td><span dir=\"rtl\">مموه يعمل</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">د</span></td>\n<td>0</td>\n<td>1</td>\n<td><span dir=\"rtl\">اختاره 1 من 22 (4.5%): مموه غير فاعل، يُستبدل</span></td>\n</tr>\n</tbody>\n</table></div>\n<p><span dir=\"rtl\">القرار: يُراجع المدرس السؤال. إذا ثبت أن (ب) هو الصحيح يُصحَّح المفتاح وتُعاد الرصد، وإذا كان (أ) و(ب) صحيحين يُقبل الاثنان، وفق البند 5.3 من السياسة.</span></p>\n<h3><span dir=\"rtl\">6.4 مثال محلول (تخصص إنساني): سؤال في «النحو العربي»</span></h3>\n<p><span dir=\"rtl\">المفتاح = ج، وكل فئة 11 طالباً.</span></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">البديل</span></th>\n<th><span dir=\"rtl\">الفئة العليا</span></th>\n<th><span dir=\"rtl\">الفئة الدنيا</span></th>\n<th><span dir=\"rtl\">القراءة</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">أ</span></td>\n<td>1</td>\n<td>4</td>\n<td><span dir=\"rtl\">مموه فاعل يجذب الفئة الدنيا</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">ب</span></td>\n<td>2</td>\n<td>3</td>\n<td><span dir=\"rtl\">مموه فاعل</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">ج (المفتاح)</span></td>\n<td>8</td>\n<td>2</td>\n<td>p = 10 ÷ 22 = 0.45، D = 6 ÷ 11 = 0.55: سؤال ممتاز</td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">د</span></td>\n<td>0</td>\n<td>2</td>\n<td><span dir=\"rtl\">اختاره 9% من الطلبة وكلهم من الفئة الدنيا: مموه يعمل</span></td>\n</tr>\n</tbody>\n</table></div>\n<p><span dir=\"rtl\">هذا هو نمط السؤال الجيد: المفتاح يجذب الفئة العليا، وكل مموه يجذب الفئة الدنيا أكثر.</span></p>\n<h3><span dir=\"rtl\">6.5 ثبات الاختبار ككل: مثال حسابي</span></h3>\n<p><span dir=\"rtl\">امتحان من 40 سؤال اختيار من متعدد، مجموع p×q لأسئلته = 7.2، وتباين العلامات الكلية = 36.</span></p>\n<p>KR-20 = (40 ÷ 39) × (1 − 7.2 ÷ 36) = 1.026 × 0.80 ≈ <strong>0.82</strong></p>\n<p><span dir=\"rtl\">التفسير: الثبات أعلى من 0.70 المطلوب للاختبارات الصفية، بل يتجاوز 0.80 المطلوب للاختبارات عالية المخاطر. وللأسئلة الإنشائية ذات العلامات المتدرجة يُستخدم معامل ألفا كرونباخ بدلاً من KR-20.</span></p>\n<h3><span dir=\"rtl\">6.6 جدول القرار السريع</span></h3>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">الحالة</span></th>\n<th><span dir=\"rtl\">القرار</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>p بين 0.30 و 0.80، وD ≥ 0.30</td>\n<td><span dir=\"rtl\">يبقى في بنك الأسئلة</span></td>\n</tr>\n<tr>\n<td>D بين 0.20 و 0.29</td>\n<td><span dir=\"rtl\">تُراجع المموهات والصياغة</span></td>\n</tr>\n<tr>\n<td>D أقل من 0.20</td>\n<td><span dir=\"rtl\">يُعدَّل جوهرياً أو يُستبدل</span></td>\n</tr>\n<tr>\n<td>D سالب</td>\n<td><span dir=\"rtl\">يُفحص المفتاح فوراً قبل اعتماد النتائج</span></td>\n</tr>\n<tr>\n<td>p أعلى من 0.90</td>\n<td><span dir=\"rtl\">سهل جداً: يُبقى فقط إذا كان يقيس مهارة أساسية مقصودة</span></td>\n</tr>\n<tr>\n<td>p أقل من 0.20</td>\n<td><span dir=\"rtl\">صعب جداً: يُفحص الغموض ومدى تغطية الموضوع في التدريس</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">مموه يختاره أقل من 5%</span></td>\n<td><span dir=\"rtl\">يُستبدل بمموه أكثر معقولية</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">مموه تختاره الفئة العليا أكثر من الدنيا</span></td>\n<td><span dir=\"rtl\">يُفحص: قد يكون صحيحاً أو غامضاً</span></td>\n</tr>\n</tbody>\n</table></div>\n<p><span dir=\"rtl\">تنبيه: المؤشرات غير مستقرة مع الأعداد الصغيرة. لذلك تشترط السياسة التحليل الإلزامي للامتحانات التي يتقدم لها 30 طالباً فأكثر، وما دون ذلك يُقرأ بحذر ويُجمع عبر أكثر من فصل.</span></p>\n<h2><span dir=\"rtl\">الوحدة السابعة: الذكاء الاصطناعي والنزاهة والعدالة</span></h2>\n<p><span dir=\"rtl\">المهام المنزلية التقليدية (اكتب تقريراً عن…) يمكن اليوم إنجازها آلياً في دقائق. لا يكمن الحل في مطاردة الأدوات، بل في تصميم مهام تتطلب ما لا تستطيعه الأداة وحدها: بيانات محلية، وتجربة شخصية، ومراحل موثقة، ومناقشة شفوية.</span></p>\n<h3><span dir=\"rtl\">7.1 مستويات الاستخدام المسموح (من السياسة)</span></h3>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">المستوى</span></th>\n<th><span dir=\"rtl\">الوصف</span></th>\n<th><span dir=\"rtl\">مثال علمي</span></th>\n<th><span dir=\"rtl\">مثال إنساني</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">0 – ممنوع</span></td>\n<td><span dir=\"rtl\">لا استخدام</span></td>\n<td><span dir=\"rtl\">امتحان نهائي في الدوائر الكهربائية</span></td>\n<td><span dir=\"rtl\">امتحان نهائي في النحو</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">1 – مساند محدود</span></td>\n<td><span dir=\"rtl\">توليد أفكار أو تدقيق لغوي، مع الإفصاح</span></td>\n<td><span dir=\"rtl\">تدقيق لغة تقرير مختبر</span></td>\n<td><span dir=\"rtl\">اقتراح عناوين لموضوع بحث</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">2 – مدمج بإفصاح</span></td>\n<td><span dir=\"rtl\">استخدام موثق يُقيَّم توظيفه النقدي</span></td>\n<td><span dir=\"rtl\">توليد شيفرة ثم اختبارها وتصحيح أخطائها</span></td>\n<td><span dir=\"rtl\">تلخيص آلي لمقال ثم تقييم دقته مقارنة بالأصل</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">3 – جزء من المهمة</span></td>\n<td><span dir=\"rtl\">استخدام الأداة هو المهارة المقاسة</span></td>\n<td><span dir=\"rtl\">بناء نموذج تصنيف لأمراض النبات من الصور</span></td>\n<td><span dir=\"rtl\">تصميم حملة إعلانية بأدوات توليدية مع تبرير الاختيارات</span></td>\n</tr>\n</tbody>\n</table></div>\n<h3><span dir=\"rtl\">7.2 إعادة تصميم المهام غير المراقبة</span></h3>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">التخصص</span></th>\n<th><span dir=\"rtl\">المهمة التقليدية</span></th>\n<th><span dir=\"rtl\">المهمة بعد إعادة التصميم</span></th>\n<th><span dir=\"rtl\">ما الذي يجعلها أصعب للإنجاز الآلي</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">تكنولوجيا المعلومات</span></td>\n<td><span dir=\"rtl\">اكتب برنامجاً يحسب معدل الطلبة.</span></td>\n<td><span dir=\"rtl\">عدّل البرنامج المرفق ليعالج ملف العلامات (مجهول الهوية) الخاص بشعبتك، واشرح في مناقشة مدتها 5 دقائق سبب اختيارك لكل بنية برمجية.</span></td>\n<td><span dir=\"rtl\">بيانات فريدة، وشيفرة انطلاق محددة، ومناقشة شفوية</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الزراعة</span></td>\n<td><span dir=\"rtl\">اكتب تقريراً عن آفات الزيتون.</span></td>\n<td><span dir=\"rtl\">زر حقل زيتون في منطقتك، وصوّر ثلاثة أعراض إصابة، وحدد الآفة المحتملة لكل منها مع التبرير، وقارن ملاحظاتك بنتائج المصائد الفرمونية في مزرعة الجامعة.</span></td>\n<td><span dir=\"rtl\">عمل ميداني وصور أصلية وبيانات محلية</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الهندسة</span></td>\n<td><span dir=\"rtl\">اكتب تقرير تجربة قانون أوم.</span></td>\n<td><span dir=\"rtl\">اكتب التقرير من قراءات فريقك المسجلة في المختبر، وفسّر أكبر انحراف بين القيم النظرية والمقاسة ومصدره المحتمل في تجربتكم تحديداً.</span></td>\n<td><span dir=\"rtl\">بيانات مقاسة فعلياً وتحليل خطأ خاص بها</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الأدب العربي</span></td>\n<td><span dir=\"rtl\">اكتب مقالاً عن شعر المتنبي.</span></td>\n<td><span dir=\"rtl\">اختر أبياتاً من القائمة التي يوزعها المدرس، واكتب مسودة أولى في القاعة خلال 30 دقيقة، ثم طوّرها في المنزل مع سجل بالتعديلات وأسبابها.</span></td>\n<td><span dir=\"rtl\">مسودة مراقبة ومسار كتابة موثق</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">العلوم الإدارية</span></td>\n<td><span dir=\"rtl\">اكتب خطة تسويقية لشركة.</span></td>\n<td><span dir=\"rtl\">أعدّ خطة تسويقية لمنشأة صغيرة حقيقية في مدينتك بعد مقابلة صاحبها، وأرفق محضر المقابلة، ثم اعرض الخطة وأجب عن أسئلة اللجنة.</span></td>\n<td><span dir=\"rtl\">مصدر أولي خاص وعرض شفوي</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">العلوم التربوية</span></td>\n<td><span dir=\"rtl\">اكتب عن استراتيجيات التعلم النشط.</span></td>\n<td><span dir=\"rtl\">حلّل حصة نفذتها في التربية العملية: ما الاستراتيجية التي استخدمتها، وماذا حدث فعلاً، وماذا ستغيّر بناءً على ملاحظات المشرف.</span></td>\n<td><span dir=\"rtl\">تجربة شخصية وتغذية راجعة من طرف ثالث</span></td>\n</tr>\n</tbody>\n</table></div>\n<h3><span dir=\"rtl\">7.3 مهام تدمج الذكاء الاصطناعي بشكل مشروع (المستوى 2)</span></h3>\n<p><span dir=\"rtl\"><strong>مثال 7-1 (علمي – البرمجة):</strong> اطلب من أداة ذكاء اصطناعي دالة تتحقق من صحة رقم هاتف محلي. ثم اكتب خمس حالات اختبار على الأقل، منها حالتان حدّيتان، وحدد الحالات التي تفشل فيها الدالة، وصحّحها. تُمنح العلامة على حالات الاختبار والتصحيح والتبرير، لا على الشيفرة المولّدة.</span></p>\n<p><span dir=\"rtl\"><strong>مثال 7-2 (إنساني – التاريخ أو العلوم الاجتماعية):</strong> اطلب من أداة ذكاء اصطناعي تلخيصاً لفصل محدد من الكتاب المقرر. قارن التلخيص بالفصل الأصلي، وحدد ثلاثة مواضع على الأقل أغفل فيها فكرة مهمة أو أخطأ أو بالغ، مع الاستشهاد برقم الصفحة. المهارة المقاسة هنا هي القراءة الناقدة للمصادر.</span></p>\n<h3><span dir=\"rtl\">7.4 نص مقترح لورقة المهمة</span></h3>\n<blockquote>\n<p><span dir=\"rtl\"><strong>استخدام أدوات الذكاء الاصطناعي في هذه المهمة: المستوى 1.</strong> يُسمح باستخدامها لاقتراح الأفكار وتدقيق اللغة فقط. لا يُسمح باستخدامها لكتابة النص أو التحليل. اذكر في نهاية العمل اسم الأداة والغرض من استخدامها. وقد يُطلب منك مناقشة عملك شفوياً.</span></p>\n</blockquote>\n<h3><span dir=\"rtl\">7.5 التعامل مع حالات الاشتباه</span></h3>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">لا تعتمد على نتيجة أداة كشف دليلاً وحيداً، فهذه الأدوات تخطئ وقد تظلم الطلبة الذين يكتبون بلغة غير لغتهم الأم.</span></p></li>\n<li><p><span dir=\"rtl\">ابحث عن مؤشرات متعددة: فرق كبير عن مستوى الطالب في العمل المراقب، مراجع غير موجودة، محتوى لا يرتبط بما دُرِّس.</span></p></li>\n<li><p><span dir=\"rtl\">ادعُ الطالب إلى مناقشة شفوية قصيرة حول عمله، ووثّقها.</span></p></li>\n<li><p><span dir=\"rtl\">إذا استمر الاشتباه، تُحال الحالة وفق أنظمة التأديب، مع حفظ حق الطالب في الاستماع إليه.</span></p></li>\n</ol>\n<h3><span dir=\"rtl\">7.6 العدالة: أسئلة متحيزة ونسختها العادلة</span></h3>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">التخصص</span></th>\n<th><span dir=\"rtl\">السؤال المتحيز</span></th>\n<th><span dir=\"rtl\">مصدر التحيز</span></th>\n<th><span dir=\"rtl\">النسخة العادلة</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">الفيزياء</span></td>\n<td><span dir=\"rtl\">متزلج ينزلق على منحدر ثلجي بزاوية 30°…</span></td>\n<td><span dir=\"rtl\">سياق غير مألوف لمعظم الطلبة يشتت انتباههم</span></td>\n<td><span dir=\"rtl\">صندوق تُنزَل على مستوى مائل أملس بزاوية 30° في مستودع…</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">الرياضيات</span></td>\n<td><span dir=\"rtl\">نص طويل معقد لغوياً لسؤال حسابي بسيط</span></td>\n<td><span dir=\"rtl\">يقيس القراءة بدل الرياضيات، ويظلم الطلبة ذوي صعوبات القراءة</span></td>\n<td><span dir=\"rtl\">جمل قصيرة مباشرة بالمعطيات اللازمة فقط</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">العلوم الإدارية</span></td>\n<td><span dir=\"rtl\">المدير يتخذ القرار والسكرتيرة تنفذ…</span></td>\n<td><span dir=\"rtl\">صورة نمطية لأدوار الرجال والنساء</span></td>\n<td><span dir=\"rtl\">مديرة المبيعات تتخذ القرار، ومسؤول المستودع ينفذ… (تنويع الأدوار)</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">اللغة الإنجليزية</span></td>\n<td><span dir=\"rtl\">نص قرائي عن قواعد لعبة البيسبول</span></td>\n<td><span dir=\"rtl\">يستفيد منه من يعرف اللعبة مسبقاً لا من يتقن القراءة</span></td>\n<td><span dir=\"rtl\">نص عن موضوع عام مألوف للجميع، مثل تنظيم الوقت أو المياه</span></td>\n</tr>\n</tbody>\n</table></div>\n<h3><span dir=\"rtl\">7.7 الترتيبات التيسيرية في التطبيق</span></h3>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">الحالة</span></th>\n<th><span dir=\"rtl\">الترتيب المناسب</span></th>\n<th><span dir=\"rtl\">ما لا يجوز</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">طالب ضعيف البصر</span></td>\n<td><span dir=\"rtl\">خط مكبر (18 نقطة فأكثر)، أو نسخة إلكترونية مع قارئ شاشة، وزمن إضافي</span></td>\n<td><span dir=\"rtl\">حذف الأسئلة المبنية على رسوم دون بديل مكافئ</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">طالب لديه عسر قراءة موثق</span></td>\n<td><span dir=\"rtl\">زمن إضافي 25%، وقارئ للأسئلة في غير مساقات اللغة</span></td>\n<td><span dir=\"rtl\">قراءة الأسئلة في امتحان يقيس مهارة القراءة نفسها</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">طالب مصاب في يده الكاتبة</span></td>\n<td><span dir=\"rtl\">كاتب محايد أو حاسوب</span></td>\n<td><span dir=\"rtl\">إعفاء من الأسئلة المقالية</span></td>\n</tr>\n</tbody>\n</table></div>\n<h2><span dir=\"rtl\">الأنشطة التطبيقية وقوائم التحقق ومفاتيح الإجابة</span></h2>\n<p><span dir=\"rtl\">نشاط لكل جلسة تدريبية، يُنفذ في مجموعات مختلطة من التخصصات العلمية والإنسانية، لأن نظرة الزميل من تخصص آخر تكشف الغموض بسرعة.</span></p>\n<h3><span dir=\"rtl\">النشاط 1: تحسين مخرجات التعلم (الجلسة 1)</span></h3>\n<p><span dir=\"rtl\">أعد صياغة المخرجات الآتية لتصبح قابلة للقياس، ثم حدد مستواها في تصنيف بلوم:</span></p>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">(علمي) أن يعرف الطالب قواعد البيانات.</span></p></li>\n<li><p><span dir=\"rtl\">(علمي) أن يفهم الطالب التسميد.</span></p></li>\n<li><p><span dir=\"rtl\">(إنساني) أن يدرك الطالب أهمية المحاسبة.</span></p></li>\n<li><p><span dir=\"rtl\">(إنساني) أن يلمّ الطالب بالمدارس النقدية.</span></p></li>\n</ol>\n<p><strong><span dir=\"rtl\">إجابات نموذجية:</span></strong></p>\n<ol type=\"1\">\n<li><p><span dir=\"rtl\">أن يصمم الطالب مخطط قاعدة بيانات علائية لنظام تسجيل مساقات، في الصيغة الطبيعية الثالثة. (إبداع)</span></p></li>\n<li><p><span dir=\"rtl\">أن يحسب الطالب كمية السماد اللازمة لمحصول معين من نتائج تحليل التربة ونسبة العنصر في السماد. (تطبيق)</span></p></li>\n<li><p><span dir=\"rtl\">أن يسجّل الطالب العمليات المالية لمنشأة تجارية في دفتر اليومية وفق القيد المزدوج. (تطبيق)</span></p></li>\n<li><p><span dir=\"rtl\">أن يقارن الطالب بين المنهجين التاريخي والبنيوي في تحليل نص أدبي معطى. (تحليل)</span></p></li>\n</ol>\n<h3><span dir=\"rtl\">النشاط 2: اكتشف العيب وحسّن السؤال (الجلسة 2)</span></h3>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th>#</th>\n<th><span dir=\"rtl\">السؤال</span></th>\n<th><span dir=\"rtl\">مفتاح العيوب</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">أ</span></td>\n<td><span dir=\"rtl\">(تكنولوجيا المعلومات) أي مما يلي ليس من لغات البرمجة؟ أ) Python ب) Java ج) HTML د) جميع ما سبق</span></td>\n<td><span dir=\"rtl\">نفي غير مبرز، و«جميع ما سبق»، وموضوع خلافي (هل HTML لغة برمجة أم لغة ترميز؟) فيصبح المفتاح محل جدال.</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">ب</span></td>\n<td><span dir=\"rtl\">(الزراعة) النبات يحتاج إلى: أ) الماء ب) الضوء ج) ثاني أكسيد الكربون د) كل ما ذُكر</span></td>\n<td><span dir=\"rtl\">جذع ناقص لا يطرح مشكلة، وأكثر من إجابة صحيحة، والمفتاح «كل ما ذُكر» يُعرف بمجرد معرفة بديلين صحيحين.</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">ج</span></td>\n<td><span dir=\"rtl\">(اللغة العربية) الفعل المضارع هو الفعل الذي يدل على الحاضر أو المستقبل ويبدأ بأحد أحرف «أنيت»، وهو: أ) كتب ب) يكتب ج) اكتب د) كاتب</span></td>\n<td><span dir=\"rtl\">الجذع يعلّم الإجابة فيصبح السؤال بلا قيمة، والبديل (د) اسم لا فعل فهو غير متجانس. الأفضل: جملة فيها أفعال مختلفة، ويُسأل الطالب عن المضارع بينها.</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">د</span></td>\n<td><span dir=\"rtl\">(العلوم الإدارية) الميزانية: أ) وثيقة ب) خطة مالية تقديرية للإيرادات والنفقات لفترة مقبلة تُستخدم في التخطيط والرقابة ج) تقرير د) حساب</span></td>\n<td><span dir=\"rtl\">المفتاح أطول بكثير وأدق، والمموهات كلمات مفردة عامة لا تجذب أحداً.</span></td>\n</tr>\n</tbody>\n</table></div>\n<h3><span dir=\"rtl\">النشاط 3: بناء سياق وأسئلته (الجلسة 3)</span></h3>\n<p><span dir=\"rtl\">اختر سياقاً جديداً من مساقك (جدول بيانات، نص، مقطع شيفرة، موقف مهني)، واكتب عليه ثلاثة أسئلة اختيار من متعدد: فهم وتطبيق وتحليل. ثم تبادل الأسئلة مع زميل من تخصص آخر واطلب منه أن يجيب دون قراءة السياق: إذا أجاب صحيحاً فالسياق غير ضروري ويجب تعديل السؤال.</span></p>\n<h3><span dir=\"rtl\">النشاط 4: تصحيح مستقل ثم معايرة (الجلسة 4)</span></h3>\n<p><span dir=\"rtl\">صحّح الإجابات الثلاث الآتية عن المثال 5-9 (بيت المتنبي، 6 علامات) بمفردك وباستخدام السلّم، ثم قارن علاماتك بعلامات زملائك.</span></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">الإجابة</span></th>\n<th><span dir=\"rtl\">نص إجابة الطالب</span></th>\n<th><span dir=\"rtl\">العلامة المقترحة</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1</td>\n<td><span dir=\"rtl\">يقصد الشاعر ألا نثق بمن يبتسم لنا من الأعداء لأنه قد يضمر الشر. وهذا تشبيه ضمني، فقد شبّه العدو المبتسم بالأسد الذي يظهر أنيابه دون تصريح، وجاء بالحكمة مقرونة بدليل من الواقع فزادها إقناعاً.</span></td>\n<td>6 (2 + 2 + 2)</td>\n</tr>\n<tr>\n<td>2</td>\n<td><span dir=\"rtl\">الفكرة: الحذر من الأعداء. الصورة: استعارة، حيث شبّه العدو بالأسد.</span></td>\n<td><span dir=\"rtl\">1 (الفكرة ناقصة 1، نوع الصورة خاطئ 0، الأثر غائب 0)</span></td>\n</tr>\n<tr>\n<td>3</td>\n<td><span dir=\"rtl\">الأسد حيوان مفترس، وعندما يظهر أنيابه لا يكون مبتسماً بل مستعداً للهجوم، والشاعر يقول إن المظاهر خادعة. والصورة تشبيه.</span></td>\n<td><span dir=\"rtl\">3 (الفكرة 2، نوع الصورة ناقص 1، الأثر غائب 0)</span></td>\n</tr>\n</tbody>\n</table></div>\n<p><span dir=\"rtl\">أسئلة للنقاش: أين اختلفت علاماتكم؟ هل كان السلّم واضحاً في الحالات الناقصة («تشبيه» دون «ضمني»)؟ ماذا تضيفون إلى السلّم لتوحيد الحكم؟ ويُنفذ النشاط نفسه على المثال 5-8 (دالة Python) للمتدربين من التخصصات العلمية.</span></p>\n<h3><span dir=\"rtl\">النشاط 5: حساب المعاملات واتخاذ القرار (الجلسة 5)</span></h3>\n<p><span dir=\"rtl\">تقدم لامتحان 30 طالباً، فكل فئة = 8 طلاب. احسب p وD واتخذ القرار.</span></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">السؤال</span></th>\n<th>U</th>\n<th>L</th>\n<th>p (الإجابة)</th>\n<th>D (الإجابة)</th>\n<th><span dir=\"rtl\">القرار (الإجابة)</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">أ</span></td>\n<td>7</td>\n<td>2</td>\n<td>0.56</td>\n<td>0.63</td>\n<td><span dir=\"rtl\">ممتاز، يبقى</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">ب</span></td>\n<td>8</td>\n<td>8</td>\n<td>1.00</td>\n<td>0.00</td>\n<td><span dir=\"rtl\">أجاب الجميع، لا يميّز؛ يُستبدل إلا لغرض مقصود</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">ج</span></td>\n<td>2</td>\n<td>5</td>\n<td>0.44</td>\n<td>−0.38</td>\n<td><span dir=\"rtl\">تمييز سالب؛ يُفحص المفتاح فوراً</span></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">د</span></td>\n<td>5</td>\n<td>3</td>\n<td>0.50</td>\n<td>0.25</td>\n<td><span dir=\"rtl\">يُراجع لتحسين مموهاته</span></td>\n</tr>\n</tbody>\n</table></div>\n<h3><span dir=\"rtl\">النشاط 6: إعادة تصميم مهمة (الجلسة 6)</span></h3>\n<p><span dir=\"rtl\">اختر مهمة منزلية من مساقك، وأعد تصميمها باستخدام عنصرين على الأقل مما يلي: بيانات محلية، تجربة شخصية، مسودة مراقبة، مناقشة شفوية، مستوى ذكاء اصطناعي معلن. ثم اكتب نص التعليمات كما سيراه الطالب، واسترشد بالجدول في البند 7.2.</span></p>\n<h3><span dir=\"rtl\">قائمة تحقق: السؤال الإنشائي</span></h3>\n<ul>\n<li><p><span dir=\"rtl\">☐ يبدأ بفعل إجرائي محدد (قارن، علّل، قيّم، صمّم).</span></p></li>\n<li><p><span dir=\"rtl\">☐ يحدد النطاق: عدد النقاط أو المحاور أو الكلمات.</span></p></li>\n<li><p><span dir=\"rtl\">☐ العلامة مكتوبة ومتناسبة مع الجهد والزمن.</span></p></li>\n<li><p><span dir=\"rtl\">☐ يقيس مستوى لا يمكن قياسه بسؤال موضوعي.</span></p></li>\n<li><p><span dir=\"rtl\">☐ له نموذج إجابة أو سلّم معدّ مسبقاً، مع بدائل الإجابات المقبولة.</span></p></li>\n<li><p><span dir=\"rtl\">☐ ليس ضمن أسئلة اختيارية.</span></p></li>\n</ul>\n<h3><span dir=\"rtl\">قائمة تحقق: ورقة الامتحان قبل تسليمها للجنة</span></h3>\n<ul>\n<li><p><span dir=\"rtl\">☐ مخطط الاختبار مرفق والأسئلة مطابقة له.</span></p></li>\n<li><p><span dir=\"rtl\">☐ التوزيع بين الموضوعي والإنشائي ضمن المدى (40% – 70%) أو مبرر كتابياً.</span></p></li>\n<li><p><span dir=\"rtl\">☐ أوزان مستويات التفكير ضمن الجدول المعتمد لمستوى المساق.</span></p></li>\n<li><p><span dir=\"rtl\">☐ الصواب والخطأ لا يتجاوز 10% من العلامة.</span></p></li>\n<li><p><span dir=\"rtl\">☐ مواقع المفاتيح موزعة بالتساوي تقريباً.</span></p></li>\n<li><p><span dir=\"rtl\">☐ حُلّ الامتحان كاملاً من زميل أو من المدرس نفسه، والزمن المخصص كافٍ.</span></p></li>\n<li><p><span dir=\"rtl\">☐ الأسئلة المكررة من الفصل السابق لا تتجاوز 30%.</span></p></li>\n<li><p><span dir=\"rtl\">☐ الغلاف والتعليمات وفق النموذج الموحد، مع مستوى استخدام الذكاء الاصطناعي.</span></p></li>\n<li><p><span dir=\"rtl\">☐ اللغة خالية من التحيز والتعقيد غير اللازم.</span></p></li>\n</ul>\n<h3><span dir=\"rtl\">التقييم الذاتي للمتدرب (قبل البرنامج وبعده)</span></h3>\n<p><span dir=\"rtl\">ضع تقديراً من 1 (لا أستطيع) إلى 5 (أستطيع بثقة وأدرّب غيري).</span></p>\n<div class=\"tw\"><table>\n<colgroup>\n<col />\n<col />\n<col />\n</colgroup>\n<thead>\n<tr>\n<th><span dir=\"rtl\">المهارة</span></th>\n<th><span dir=\"rtl\">قبل</span></th>\n<th><span dir=\"rtl\">بعد</span></th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><span dir=\"rtl\">صياغة مخرجات تعلم قابلة للقياس</span></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">بناء مخطط اختبار متوازن</span></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">كتابة أسئلة اختيار من متعدد تقيس التحليل</span></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">بناء سلّم تقدير تحليلي</span></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">حساب معاملات الصعوبة والتمييز وتفسيرها</span></td>\n<td></td>\n<td></td>\n</tr>\n<tr>\n<td><span dir=\"rtl\">تصميم مهام تراعي الذكاء الاصطناعي والعدالة</span></td>\n<td></td>\n<td></td>\n</tr>\n</tbody>\n</table></div>\n<h3><span dir=\"rtl\">المراجع</span></h3>\n<ul>\n<li><p>AERA, APA &amp; NCME (2014). <em>Standards for Educational and Psychological Testing</em>. Washington, DC: AERA.</p></li>\n<li><p>Anderson, L. W., &amp; Krathwohl, D. R. (Eds.) (2001). <em>A Taxonomy for Learning, Teaching, and Assessing</em>. New York: Longman.</p></li>\n<li><p>Haladyna, T. M., &amp; Rodriguez, M. C. (2013). <em>Developing and Validating Test Items</em>. New York: Routledge.</p></li>\n<li><p>Brookhart, S. M. (2013). <em>How to Create and Use Rubrics for Formative Assessment and Grading</em>. Alexandria, VA: ASCD.</p></li>\n</ul>\n";
